// A web browser on the frame's screen. Type an address (or words to search
// for), and the page is downloaded, cleaned and drawn as JSX: html.ts reads
// the HTML in one pass and keeps the text, links, pictures, tables, lists and
// GET forms, with the colors and sizes its style sheets give them (css.ts);
// scripts, styles, frames, video and hidden parts are dropped. view.tsx draws
// what is left, and a tap on a link opens it here. Hold a link for its menu:
// open it, or show its QR code to open it on a phone.
//
// A page is read in pieces (byte ranges, where the server answers them) and
// slimmed as it comes (html.ts slimPush: scripts, comments, big SVG and the
// style rules nothing here reads go), so a news site of seven megabytes whose
// words start three megabytes in shows on an ESP32 too. Nothing in it is one
// site's: every fix is HTML, CSS or HTTP as a browser reads them.
//
// The page downloads with frameos.useFetch: off the render where the frame
// pumps promises (a tap answers at once and the page follows), in the render
// where it does not (e-paper: one refresh with the page). Back and forward are
// the toolbar's arrows and the frame's own back / forward (a HyperPixel's edge
// swipes, a reTerminal's keys). Where you have been is kept with
// frameos.remember, so a frame that let the interpreter go opens on the same
// page, scrolled where it was. Tested against Hacker News, news sites (CNN,
// the BBC, the Guardian), GitHub, Wikipedia, Tailwind sites and text-only ones.

import { convert, scanHead, slimmer, slimPush, slimText, type Page, type Slim } from './html'
import { pageClasses, slimCss } from './css'
import { MAX_SVG_TEXT, parseSvg, type SvgEl } from './svg'
import { jsxSource, PICTURE_PIXELS, renderPage, type Act } from './view'

const HOME = 'https://news.ycombinator.com/'
const SEARCH = 'https://lite.duckduckgo.com/lite/?q='
const MAX_HISTORY = 40
const HEADERS = {
  'User-Agent': 'Mozilla/5.0 (compatible; FrameOS browser)',
  Accept: 'text/html,application/xhtml+xml,text/plain;q=0.9,*/*;q=0.5',
}
const ZOOMS = [0.6, 0.7, 0.8, 0.9, 1, 1.15, 1.3, 1.5, 1.75, 2]

// frameos.useFetch is experimental (docs/async-js.md): the editor's
// declarations do not have it yet.
const useFetch = (url: string, init: Record<string, any>) => (frameos as any).useFetch(url, init)

type Entry = { u: string; y: number; p?: number } // p: the part of the page showing (view.tsx partsOf)
type Nav = { list: Entry[]; at: number }
// at: the byte the next piece of the page starts at; slim: what is kept of it.
type Load = { url: string; n: number; html?: string; status?: number; sheets?: string[]; at?: number; slim?: Slim;
  plain?: boolean; sized?: boolean }

let page: Page | null = null // the page showing
let loading: Load | null = null
let loadSeq = 0
let failure: { url: string; why: string } | null = null
let typed: string | null = null // the address while it is being typed
let held = '' // the link whose menu is open
let source = false // the page as JSX
let scrollY = 0 // where the page is scrolled to (UI pixels)
let scrollAttr = 0 // what the page box is told: changed only to move it
let rev = 0 // the fields' values changed
let hops = 0 // the refreshes followed in a row (<meta http-equiv="refresh">)
let drewPage = false // the last render drew a page
let fetchesWait = false // useFetch answers later (a frame that pumps promises), not in the render
const pages = new Map<string, Page>() // pages seen, newest last
const sheets = new Map<string, string>() // style sheets by URL
// On an ESP32 the classes of the site's pages seen so far, each with when it
// was first seen: a sheet is kept cut down to them (slimCss), and serves a
// page whose classes it was cut for (`sheetUpto`).
let siteOf = ''
let siteClasses = new Map<string, number>()
const sheetUpto = new Map<string, number>()
const values = new Map<string, string>() // what was typed into a page's fields
const svgs = new Map<string, SvgEl | null>() // SVG pictures by URL, read (null: not one)

// An ESP32's pictures are the app's own: kept pictures (fetchImage keep) of
// the part showing, let go as soon as another part or page needs room. An
// <img src="https://…"> is the runtime's, and the runtime keeps those it drew
// up to eight 480x480 photos' worth (3.7 MB in RGB565) whatever page they were
// on, which a board of 8 MB does not have beside a page; a browser sees new
// pictures on every page. A frame that shows changes at once (an LCD) gets the
// page's words first and its pictures a few at a time, a render a second; an
// e-paper one all in the render that draws the page.
type Pic = { ref: any; owner: string; walk: number }
const pics = new Map<string, Pic>() // by url and size; ref null: it did not come
let picOwner = '' // the part being drawn (view.tsx renderPage)
let picWalk = 0
let picMode: 'all' | 'some' | 'none' = 'all'
let picSpent = 0 // ms this render spent fetching pictures
let picPending = false // pictures still to come
let picPass = 0 // what PageView is drawn again for while pictures come

function picture(url: string, width: number, height: number, cover: boolean): any {
  // Kept at PICTURE_PIXELS at most, its shape, and drawn stretched to its box.
  const s = Math.min(1, Math.sqrt(PICTURE_PIXELS / (width * height)))
  const w = Math.max(1, Math.round(width * s))
  const h = Math.max(1, Math.round(height * s))
  const key = `${w}x${h}${cover ? 'c' : ''} ${url}`
  const have = pics.get(key)
  if (have) {
    have.owner = picOwner
    have.walk = picWalk
    return have.ref
  }
  if (picMode === 'none' || (picMode === 'some' && picSpent >= 400)) {
    picPending = true
    return null
  }
  release(picOwner) // room first: the pictures of other parts and pages go
  const t0 = Date.now()
  let answer: any = null
  try {
    answer = frameos.fetchImage(url, { keep: true, width: w, height: h, fit: cover ? 'cover' : 'contain', headers: HEADERS } as any)
  } catch (e) {
    answer = null
  }
  picSpent += Date.now() - t0
  const ref = answer && answer.image ? answer.image : null
  pics.set(key, { ref, owner: picOwner, walk: picWalk })
  return ref
}

// Lets go of the pictures of every part but `owner`'s.
function release(owner: string) {
  for (const [k, p] of pics) {
    if (p.owner === owner) continue
    if (p.ref) frameos.releaseImage(p.ref)
    pics.delete(k)
  }
}

function walk(owner: string, done: boolean) {
  if (!done) {
    picOwner = owner
    picWalk++
    return
  }
  // The part's pictures at a size it no longer draws (a zoom) go.
  for (const [k, p] of pics) {
    if (p.owner !== owner || p.walk === picWalk) continue
    if (p.ref) frameos.releaseImage(p.ref)
    pics.delete(k)
  }
}

const kept = (key: string, empty: any) => {
  const value = frameos.recall(key)
  return value === undefined || value === null ? empty : value
}

function readNav(app: any): Nav {
  const nav = kept('nav', null)
  if (nav && Array.isArray(nav.list) && nav.list.length) return nav
  return { list: [{ u: homeOf(app), y: 0 }], at: 0 }
}
const saveNav = (nav: Nav) => frameos.remember('nav', nav)
const homeOf = (app: any) => normalize(String(app.state.homepage || app.config.homepage || HOME)) || HOME

// What was typed as a URL: an address, or words to search for.
export function normalize(text: string): string {
  const t = text.trim()
  if (!t) return ''
  if (/^https?:\/\//i.test(t)) return t
  if (/^[\w-]+(\.[\w-]+)+(:\d+)?(\/\S*)?$/.test(t) || /^localhost(:\d+)?(\/|$)/.test(t)) return 'http' + (/^(localhost|\d+\.\d+\.\d+\.\d+)/.test(t) ? '' : 's') + '://' + t
  return SEARCH + encodeURIComponent(t)
}

// A search result's link is DuckDuckGo's redirect: the page it names instead.
function unwrap(url: string): string {
  const m = /^https?:\/\/(?:html\.|lite\.)?duckduckgo\.com\/l\/\?(?:.*&)?uddg=([^&]+)/.exec(url)
  if (m) {
    try {
      return decodeURIComponent(m[1])
    } catch (e) {
      return url
    }
  }
  return url
}

const appRef: { app: any } = { app: null }

// One app object is one browser: the interpreter's. A new one (a test's
// makeApp) starts with nothing open.
function bind(app: any) {
  if (appRef.app === app) return
  appRef.app = app
  page = null
  loading = null
  failure = null
  typed = null
  held = ''
  source = false
  scrollY = 0
  pages.clear()
  values.clear()
  pics.clear()
  siteOf = ''
  picOwner = ''
  drewPage = false
  fetchesWait = false
  ranged.clear()
}

function jumpTo(y: number) {
  // scrollTop moves the box only when it changes (docs/jsx-ui.md): the same
  // place again is told a hair apart.
  scrollAttr = scrollAttr === y ? y + 0.01 : y
  scrollY = y
}

function open(url: string) {
  const app = appRef.app
  const nav = readNav(app)
  nav.list[nav.at].y = scrollY
  nav.list = nav.list.slice(0, nav.at + 1)
  nav.list.push({ u: unwrap(url), y: 0 })
  if (nav.list.length > MAX_HISTORY) nav.list = nav.list.slice(-MAX_HISTORY)
  nav.at = nav.list.length - 1
  saveNav(nav)
  typed = null
  held = ''
  source = false
  failure = null
}

function step(by: number): boolean {
  const nav = readNav(appRef.app)
  const at = nav.at + by
  if (at < 0 || at >= nav.list.length) return false
  nav.list[nav.at].y = scrollY
  nav.at = at
  saveNav(nav)
  typed = null
  held = ''
  failure = null
  return true
}

function reload() {
  const nav = readNav(appRef.app)
  pages.delete(nav.list[nav.at].u)
  nav.list[nav.at].y = scrollY
  saveNav(nav)
  page = null
  loading = null
  failure = null
}

function submit(form: number) {
  if (!page || !page.forms[form]) return
  const f = page.forms[form]
  const parts: string[] = []
  f.fields.forEach((field, i) => {
    if (field.type === 'submit') return
    const value = values.get(`${page!.url}|${form}|${i}`) ?? field.value
    parts.push(encodeURIComponent(field.name) + '=' + encodeURIComponent(value).replace(/%20/g, '+'))
  })
  open(f.action + (parts.length ? '?' + parts.join('&') : ''))
}

const act: Act = {
  go: (url) => open(url),
  hold: (url) => {
    held = url
  },
  value: (form, field) => {
    const key = `${page ? page.url : ''}|${form}|${field}`
    return values.get(key) ?? (page && page.forms[form] ? page.forms[form].fields[field].value : '')
  },
  type: (form, field, value) => {
    const at = value.indexOf('\n')
    values.set(`${page ? page.url : ''}|${form}|${field}`, at < 0 ? value : value.slice(0, at))
    rev++
    if (at >= 0) submit(form)
  },
  submit,
  svg: (url) => svgs.get(url) || null,
  picture: undefined,
  walk,
  part: (n) => {
    const nav = readNav(appRef.app)
    nav.list[nav.at].p = n
    nav.list[nav.at].y = 0
    saveNav(nav)
    jumpTo(0)
  },
}

// Bytes `from` to `to` of a URL, as text (null while they are on their way).
// A server that sends it whole answers 200; one that will not answer a range
// at all (416 for the first bytes) is asked for the whole.
function rangeFetch(url: string, from: number, to: number, init: Record<string, any>) {
  let answer = useFetch(url, { as: 'text', headers: { ...HEADERS, Range: `bytes=${from}-${to}` }, ...init })
  if (answer.loading && answer.data === undefined) {
    fetchesWait = true
    return null
  }
  if (from === 0 && answer.status === 416) {
    answer.data = ''
    answer = useFetch(url, { as: 'text', headers: HEADERS, ...init })
    if (answer.loading && answer.data === undefined) return null
  }
  const out = { status: answer.status as number, ok: !!answer.ok, text: String(answer.data ?? ''),
    error: String(answer.error || (answer.data === undefined ? `HTTP ${answer.status}` : '')) }
  answer.data = '' // read from here on: let it go
  return out
}

// The charsets a byte is a letter in (windows-1252 for them all, as browsers
// read latin-1), and what its bytes 0x80 to 0x9f are.
const SINGLE_BYTE = /charset\s*=\s*["']?\s*(iso-8859-1|iso-8859-15|latin-?1|windows-1252|cp1252)\b/i
const CP1252 = '€\u0081‚ƒ„…†‡ˆ‰Š‹Œ\u008dŽ\u008f\u0090‘’“”•–—˜™š›œ\u009džŸ'

function singleByte(url: string, bytes: number): string | null {
  const answer = (frameos as any).httpRequest(url, { headers: { ...HEADERS, Range: `bytes=0-${bytes - 1}` }, base64: true,
    timeoutMs: 20000 })
  if (!answer || !answer.bodyBase64 || answer.status >= 400) return null
  return atob(answer.bodyBase64).replace(/[\x80-\x9f]/g, (c) => CP1252[c.charCodeAt(0) - 0x80])
}

// How many bytes a text is in UTF-8.
function utf8Length(text: string): number {
  let n = text.length
  for (let i = 0; i < text.length; i++) {
    const c = text.charCodeAt(i)
    if (c >= 0x80) n += c >= 0x800 && (c < 0xd800 || c > 0xdfff) ? 2 : 1
  }
  return n
}

// A text that is not HTML, kept as it is.
function slimPlain(slim: Slim, text: string, room: number) {
  const part = text.slice(0, Math.max(0, room - slim.size))
  slim.out.push(part)
  slim.size += part.length
  if (slim.size >= room) slim.ended = true
}

// A page from what was downloaded: HTML, plain text, or a picture.
function pageFrom(load: Load, embedded: boolean, viewport: number): Page {
  const html = load.html || ''
  const text = !load.plain
    ? html
    : '<pre>' + html.slice(0, 200000).replace(/&/g, '&amp;').replace(/</g, '&lt;') + '</pre>'
  const css = (load.sheets || []).map((u) => sheets.get(u) || '')
  return convert(text, load.url, { sheets: css, sheetUrls: load.sheets, viewport, maxImages: embedded ? 12 : 40,
    maxRuns: embedded ? 8000 : 30000, maxSvg: embedded ? 1500 : 4000, maxSvgFiles: embedded ? 4 : 6,
    maxRules: embedded ? 4000 : 30000, maxNest: embedded ? 14 : 200 })
}

function imagePage(url: string): Page {
  return {
    url,
    title: url.slice(url.lastIndexOf('/') + 1),
    bg: '#202020',
    root: { k: 'b', c: [{ k: 't', align: 'center', pre: false, runs: [{ img: url, w: 0, h: 0, alt: '' }] }] },
    forms: [],
    svgs: [],
    truncated: false,
    stats: { runs: 1, images: 1, links: 0 },
  }
}

function remember(p: Page, embedded: boolean) {
  pages.delete(p.url)
  pages.set(p.url, p)
  while (pages.size > (embedded ? 1 : 4)) pages.delete(pages.keys().next().value as string)
}

// Moves the download of `url` along: the page, then its style sheets, then the
// page drawn. Returns the page once it is in.
// Whether a host answers a range of bytes (206) rather than all of them: its
// robots.txt asked for 16 bytes. Some servers say they do (Accept-Ranges) and
// send a page whole all the same.
const ranged = new Map<string, boolean>()
function answersRanges(url: string): boolean {
  const origin = (/^https?:\/\/[^/?#]+/i.exec(url) || [''])[0]
  if (!origin) return false
  let known = ranged.get(origin)
  if (known === undefined) {
    try {
      const answer = (frameos as any).httpRequest(origin + '/robots.txt', { headers: { ...HEADERS, Range: 'bytes=0-15' },
        timeoutMs: 8000 })
      known = !!answer && answer.status === 206
    } catch (e) {
      known = false
    }
    ranged.set(origin, known)
  }
  return known
}

// A page too big to be downloaded whole, from a server that sends it only
// whole: why not, or '' to go on. Asked on an ESP32 before the download, which
// holds a page about twice over as it comes in. A server that leaves its
// length out (or past the headers a frame keeps) is taken at its word.
function tooBig(url: string, most: number): string {
  if (answersRanges(url)) return ''
  let length = 0
  try {
    const answer = (frameos as any).httpRequest(url, { method: 'HEAD', headers: HEADERS, timeoutMs: 10000 })
    length = Number((answer && answer.headers && answer.headers['content-length']) || 0)
  } catch (e) {
    return ''
  }
  if (!(length > most)) return ''
  return `This page is ${(length / 1048576).toFixed(1)} MB and its server sends it only whole, more than this frame can download at once.`
}

function fetchPage(url: string, embedded: boolean, viewport: number, most = 0): Page | null {
  if (!loading || loading.url !== url) loading = { url, n: ++loadSeq }
  const load = loading
  if (/\.(png|jpe?g|gif|webp|bmp|svg)(\?[^/]*)?$/i.test(url)) {
    loading = null
    return imagePage(url)
  }
  if (load.html === undefined) {
    // The page in pieces (byte ranges, where the server answers them; one
    // that does not sends it whole), each slimmed as it comes: scripts and
    // the like go, so a page whose words start megabytes in still shows.
    // A piece is one JS string, two bytes a letter once one letter is past
    // Latin-1 (45 of GitHub's 537 KB are), and its first lines are a copy
    // of it: on an 8 MB board a page or two in, a block of 1 MB is not there.
    const piece = embedded ? 256 * 1024 : 2048 * 1024
    const room = embedded ? 640 * 1024 : 1536 * 1024
    if (!load.slim) {
      load.slim = slimmer(embedded ? 192 * 1024 : 512 * 1024, viewport)
      load.at = 0
    }
    const slim = load.slim
    if (most > 0 && !load.sized) {
      load.sized = true
      const why = tooBig(url, most)
      if (why) {
        failure = { url, why }
        loading = null
        load.slim = undefined
        return null
      }
    }
    for (;;) {
      const at = load.at as number
      const answer = rangeFetch(url, at, at + piece - 1, { timeoutMs: 20000, n: load.n })
      if (!answer) return null
      const { status, error, text } = answer
      if (at === 0 && (error || (!answer.ok && !text))) {
        failure = { url, why: error || `HTTP ${status}` }
        loading = null
        load.slim = undefined
        return null
      }
      // A later piece that fails, or one past the end (416), ends the page.
      const fine = !error && status !== 416 && (at === 0 || status === 206)
      if (at === 0) {
        load.status = status
        const head = text.slice(0, 2048).trimStart().toLowerCase()
        load.plain = !(head.startsWith('<') || /<(html|body|div|p|table|a|head)[\s>]/.test(head))
      }
      if (fine && at === 0 && !load.plain && text.indexOf('\ufffd') >= 0 && SINGLE_BYTE.test(text.slice(0, 4096))) {
        // A page in a single-byte charset, its letters lost read as UTF-8:
        // its bytes again, read as that charset.
        const again = singleByte(url, room)
        if (again !== null) {
          slimPush(slim, again, true, room)
          break
        }
      }
      const more = fine && status === 206 && utf8Length(text) >= piece - 4 && at + piece < (embedded ? 8 : 48) * 1048576
      if (fine) {
        if (load.plain) slimPlain(slim, text, room)
        else slimPush(slim, text, !more, room)
      }
      if (!more || slim.ended) break
      load.at = at + piece
    }
    load.html = slimText(slim)
    load.slim = undefined
    load.sheets = scanHead(load.html, url, 24).sheets
  }
  // The sheets in the page's order while there is room for them (slimmed). On
  // an ESP32 each is cut down to the rules the site's pages' classes can
  // match (slimCss): a design system's sheets are megabytes, of which a page
  // uses a few dozen KB, so all of them fit (a Pi keeps them whole).
  let cssRoom = embedded ? 384 * 1024 : 2048 * 1024
  const fetched: string[] = []
  let newest = 0 // the latest of this page's classes to be first seen
  if (embedded) {
    const site = (/^https?:\/\/[^/?#]+/i.exec(url) || [''])[0]
    if (site !== siteOf) {
      siteOf = site
      siteClasses = new Map()
    }
    for (const c of pageClasses(load.html || '')) {
      let at = siteClasses.get(c)
      if (at === undefined) siteClasses.set(c, (at = siteClasses.size))
      if (at > newest) newest = at
    }
  }
  for (const sheet of load.sheets || []) {
    if (cssRoom <= 0) break
    fetched.push(sheet)
    if (sheets.has(sheet) && (!embedded || (sheetUpto.get(sheet) ?? -1) > newest)) {
      cssRoom -= (sheets.get(sheet) as string).length
      continue
    }
    // A style sheet's first bytes, kept slimmed (slimCss): what it holds
    // for the width the page is laid out at.
    const most = embedded ? 384 * 1024 : 1024 * 1024
    const answer = rangeFetch(sheet, 0, most - 1, { timeoutMs: 10000, n: load.n }) // n: asked again for this page, not the answer let go of
    if (!answer) return null
    const css = answer.ok ? slimCss(answer.text.slice(0, most), viewport, embedded ? new Set(siteClasses.keys()) : undefined) : ''
    sheets.delete(sheet)
    sheets.set(sheet, css)
    sheetUpto.set(sheet, siteClasses.size)
    cssRoom -= css.length
    // Kept for the next page of the site, up to 16 (on an ESP32, those of
    // this page and as much again: they are the interpreter's memory).
    let kept = 0
    for (const v of sheets.values()) kept += v.length
    while (sheets.size > 32 || (embedded && sheets.size > 1 && kept > 768 * 1024)) {
      const oldest = sheets.keys().next().value as string
      kept -= (sheets.get(oldest) as string).length
      sheets.delete(oldest)
      sheetUpto.delete(oldest)
    }
  }
  load.sheets = fetched
  const p = pageFrom(load, embedded, viewport)
  loading = null
  return p
}

const PageView = memo((props: any) => {
  act.picture = props.budget > 0 ? picture : undefined
  return renderPage(props.page, props.width, { k: props.k, minPx: props.minPx, ink: props.ink, slim: props.budget > 0 }, act,
    props.part, props.budget)
})

// How much of a page is drawn at once, in KB of what the frame keeps of its
// layout and pictures (view.tsx partsOf). An ESP32 keeps them in the PSRAM its
// canvas leaves (RGB565: two bytes a pixel) past the runtime's own, half as
// much again while a part is laid out, and the part before until the next is
// drawn (a page before comes down first: get's "Loading"). A Pi has room for
// any page.
function pageBudget(app: any, embedded: boolean): number {
  if (!embedded) return 0
  // 16 MB boards run four windows, 8 MB ones two (one beside a 13.3" colour canvas).
  const psram = (app.frame.windows || 2) >= 4 ? 16384 : 8192
  const scale = app.frame.scale || 1
  const canvas = (app.frame.width * app.frame.height * scale * scale * 2) / 1024
  return Math.max(600, Math.round((psram - 2324 - canvas) / 2.7))
}

const SourceView = memo((props: any) => {
  const lines = jsxSource(props.page, { k: props.k, minPx: props.minPx, ink: props.ink }, 400)
  return (
    <div className={`flex flex-col p-[8px] bg-[#1e1e1e] text-[#d4d4d4] font-mono text-[${props.minPx + 1}px] leading-[${Math.round((props.minPx + 1) * 1.4)}px]`}>
      {lines.map((line: string) => {
        const indent = line.length - line.trimStart().length
        return (
          <div className="whitespace-nowrap truncate">
            {' '.repeat(indent) + line.trimStart()}
          </div>
        )
      })}
    </div>
  )
})

const ICONS = {
  back: 'M20,11V13H8L13.5,18.5L12.08,19.92L4.16,12L12.08,4.08L13.5,5.5L8,11H20Z',
  forward: 'M4,11V13H16L10.5,18.5L11.92,19.92L19.84,12L11.92,4.08L10.5,5.5L16,11H4Z',
  reload:
    'M17.65,6.35C16.2,4.9 14.21,4 12,4A8,8 0 0,0 4,12A8,8 0 0,0 12,20C15.73,20 18.84,17.45 19.73,14H17.65C16.83,16.33 14.61,18 12,18A6,6 0 0,1 6,12A6,6 0 0,1 12,6C13.66,6 15.14,6.69 16.22,7.78L13,11H20V4L17.65,6.35Z',
  stop: 'M19,6.41L17.59,5L12,10.59L6.41,5L5,6.41L10.59,12L5,17.59L6.41,19L12,13.41L17.59,19L19,17.59L13.41,12L19,6.41Z',
  home: 'M10,20V14H14V20H19V12H22L12,3L2,12H5V20H10Z',
  code: 'M14.6,16.6L19.2,12L14.6,7.4L16,6L22,12L16,18L14.6,16.6M9.4,16.6L4.8,12L9.4,7.4L8,6L2,12L8,18L9.4,16.6Z',
  minus: 'M19,13H5V11H19V13Z',
  plus: 'M19,13H13V19H11V13H5V11H11V5H13V11H19V13Z',
}

export function onEvent(app: any, context: any) {
  bind(app)
  if (context.event === 'back') return step(-1)
  if (context.event === 'forward') return step(1)
  return false
}

// A round panel: the address in the arc at the top, the buttons in the arc at
// the bottom, and the page between them as wide as the circle lets it be.
export function get(app: any, context: any) {
  if (!context || context.round !== true) return draw(app, context)
  const W = context.imageWidth
  const H = context.imageHeight
  const R = Math.min(W, H) / 2 - 12
  const chord = (dy: number) => Math.floor(2 * Math.sqrt(Math.max(0, R * R - dy * dy)))
  const top = Math.round(H / 2 - R * 0.66)
  const bottom = Math.round(H / 2 + R * 0.58)
  const roundBrowser = { W, H, R, chord, top, bottom }
  return draw(app, { ...context, imageWidth: chord(R * 0.66), imageHeight: bottom - top, roundBrowser })
}

function draw(app: any, context: any) {
  bind(app)
  const paper = app.frame.paper === true
  const ink = paper || app.frame.color === false
  const embedded = app.frame.embedded === true
  const turned = (app.frame.rotate || 0) % 180 !== 0
  const width = (context && context.imageWidth) || (turned ? app.frame.height : app.frame.width)
  const height = (context && context.imageHeight) || (turned ? app.frame.width : app.frame.height)
  // The chrome's size by the frame, as the Terminal sample's text: twice it on a
  // 4K screen or large e-paper, smaller under 480.
  const shortSide = Math.min(app.frame.width, app.frame.height)
  const z = shortSide >= (paper ? 1000 : 2160) ? 2 : shortSide >= 480 ? 1 : Math.max(0.75, shortSide / 480)
  const zoomAt = Math.max(0, Math.min(ZOOMS.length - 1, Number(kept('zoom', 4))))
  const k = Math.round(z * 1.2 * ZOOMS[zoomAt] * 100) / 100
  const minPx = Math.round(10 * z * Math.min(1, ZOOMS[zoomAt] + 0.1))

  // A new home page in the scene's settings is opened.
  const home = homeOf(app)
  if (kept('home', '') !== home) {
    frameos.remember('home', home)
    if (kept('nav', null)) open(home)
  }

  const nav = readNav(app)
  const entry = nav.list[nav.at]
  const fast = app.frame.fast ?? !paper
  // On an ESP32 whose downloads come in the render (the preview, e-paper), a
  // page is let go of before the next is downloaded and laid out: the frame
  // keeps the last page it drew until it draws another, and both with a
  // download did not fit 8 MB. One render of "Loading" between them, as a
  // frame that downloads between renders shows anyway; where a change costs a
  // refresh, only before a page that may come whole (answersRanges).
  let clearing = false
  for (let tries = 0; tries < 4 && (!page || page.url !== entry.u); tries++) {
    const seen = pages.get(entry.u)
    if (seen) {
      page = seen
      jumpTo(entry.y)
    } else if (!failure || failure.url !== entry.u) {
      if (embedded && drewPage && !fetchesWait && (!loading || loading.url !== entry.u) && (fast || !answersRanges(entry.u))) {
        clearing = true
        break
      }
      // The width it is laid out at, in CSS pixels, for its @media rules.
      const p = fetchPage(entry.u, embedded, Math.round((width - 4 * z) / k), pageBudget(app, embedded) * 800)
      if (p && p.refresh && p.refresh !== p.url && hops < 3 && /^https?:/.test(p.refresh)) {
        // A page that sends the browser on (<meta http-equiv="refresh">): the
        // page it names, in its place in the history.
        hops++
        entry.u = p.refresh
        entry.y = 0
        saveNav(nav)
        continue
      }
      if (p) {
        hops = 0
        page = p
        remember(p, embedded)
        jumpTo(entry.y)
      }
    }
    break
  }
  const showing = page && page.url === entry.u ? page : null
  // The page's SVG pictures, after it shows: each drawn when it is in.
  if (showing && !source) {
    for (const url of showing.svgs) {
      if (svgs.has(url)) continue
      const answer = useFetch(url, { as: 'text', headers: HEADERS, timeoutMs: 10000 })
      if (answer.loading && answer.data === undefined) continue
      svgs.set(url, answer.ok ? parseSvg(String(answer.data ?? '').slice(0, MAX_SVG_TEXT + 1)) : null)
      answer.data = ''
      rev++
      while (svgs.size > (embedded ? 8 : 24)) svgs.delete(svgs.keys().next().value as string)
    }
  }
  // Pictures: all in this render where a change costs a refresh, else what
  // 400 ms fetches, none in the render that first shows a part.
  const shown = showing ? `${showing.url}#${entry.p || 0}` : ''
  picMode = !fast ? 'all' : shown !== picOwner ? 'none' : 'some'
  if (shown !== picOwner) release(shown)
  picSpent = 0
  if (picPending) picPass++
  picPending = false
  const busy = !showing && !!loading
  const failed = !showing && failure && failure.url === entry.u ? failure.why : ''

  const bar = Math.round(38 * z)
  const icon = Math.round(20 * z)
  const text = Math.round(15 * z)
  // The browser's own parts take the look of a desktop around it (`look`,
  // docs/jsx-ui.md "Themes"): its toolbar a bar, its buttons buttons, the
  // address a field. Without one, a light toolbar over the pages, mostly
  // light; black on white where the panel draws in inks. The page itself is
  // the web's, never themed.
  const button = (path: string, onClick: () => void, enabled = true, lit = false) => (
    <div
      look={lit ? 'selected' : 'button'}
      className={`flex items-center justify-center w-[${bar}px] h-[${bar}px] shrink-0 ${
        ink ? (lit ? 'bg-[#000000] text-[#ffffff]' : '') : lit ? 'bg-[#d3e3fd] text-[#0b57d0]' : enabled ? 'active:bg-[#d4d6d9] hover:bg-[#e3e5e8]' : ''
      } rounded-[${Math.round(4 * z)}px] cursor-pointer`}
      onClick={enabled ? onClick : () => {}}
    >
      <svg viewBox="0 0 24 24" className={`w-[${icon}px] h-[${icon}px] ${enabled ? '' : 'opacity-40'}`}>
        <path d={path} fill="currentColor" />
      </svg>
    </div>
  )
  const address = typed ?? entry.u
  const contentW = width - Math.round(4 * z)
  const quiet = ink ? 'text-[#000000]' : 'text-[#5f6368]'
  const plainButton = ink ? 'border-2 border-[#000000] text-[#000000] bg-[#ffffff]' : 'border border-[#c4c7c5] text-[#1f1f1f] bg-[#ffffff] active:bg-[#e3e5e8]'

  const backButton = button(ICONS.back, () => step(-1), nav.at > 0)
  const forwardButton = button(ICONS.forward, () => step(1), nav.at < nav.list.length - 1)
  const reloadButton = button(busy ? ICONS.stop : ICONS.reload, () => {
    if (busy) {
      loading = null
      failure = { url: entry.u, why: 'Stopped' }
    } else reload()
  })
  const homeButton = button(ICONS.home, () => open(homeOf(app)))
  const addressField = (
    <input
      look="field"
      className={`flex-1 min-w-0 h-[${bar - Math.round(10 * z)}px] px-[${Math.round(8 * z)}px] rounded-[${Math.round(4 * z)}px] text-[${text}px] ${
        ink ? 'border border-[#000000] text-[#000000] bg-[#ffffff]' : 'border border-[#d3d6da] bg-[#ffffff] text-[#1f1f1f] focus:border-[#0b57d0]'
      }`}
      value={address}
      placeholder="Search or type an address"
      onChange={(e: any) => {
        typed = String(e.target.value)
      }}
      onKeyDown={(e: any) => {
        if (e.key === 'Enter') {
          const url = normalize(typed ?? address)
          if (url) open(url)
        } else if (e.key === 'Escape') typed = null
      }}
    />
  )
  const minusButton = button(ICONS.minus, () => frameos.remember('zoom', Math.max(0, zoomAt - 1)), zoomAt > 0)
  const plusButton = button(ICONS.plus, () => frameos.remember('zoom', Math.min(ZOOMS.length - 1, zoomAt + 1)), zoomAt < ZOOMS.length - 1)
  const sourceButton = button(ICONS.code, () => {
    source = !source
    jumpTo(0)
  }, !!showing, source && !!showing)
  const pageBox = (
    <div
      className="flex flex-col flex-1 min-h-0 overflow-y-auto"
      scrollTop={scrollAttr}
      onScroll={(e: any) => {
        scrollY = e.scrollTop
      }}
    >
      {showing ? (
        source ? (
          <SourceView page={showing} k={k} minPx={minPx} ink={ink} />
        ) : (
          <PageView page={showing} width={contentW} k={k} minPx={minPx} ink={ink} rev={rev} part={entry.p || 0}
            budget={pageBudget(app, embedded)} pass={picPass} />
        )
      ) : (
        <div className={`flex flex-col items-center justify-center flex-1 gap-[${Math.round(10 * z)}px] p-[${Math.round(16 * z)}px] text-[${text}px]`}>
          {failed ? (
            <>
              <span className={`text-[${Math.round(text * 1.3)}px] font-bold`}>This page did not load</span>
              <span look="muted" className={`text-center ${quiet}`}>{failed}</span>
              <span look="muted" className={`text-center ${quiet}`}>{entry.u}</span>
              <div
                look="button"
                className={`px-[${Math.round(14 * z)}px] py-[${Math.round(6 * z)}px] rounded ${plainButton} cursor-pointer`}
                onClick={() => reload()}
              >
                Try again
              </div>
            </>
          ) : (
            <>
              <span look="muted" className={quiet}>{'Loading ' + (entry.u.replace(/^https?:\/\//, '').split('/')[0] || '') + '…'}</span>
            </>
          )}
        </div>
      )}
    </div>
  )
  const heldBox = held ? (
    <div className="absolute inset-0 flex items-center justify-center bg-black/50" onClick={() => (held = '')}>
      <div
        look="page"
        className={`flex flex-col gap-[${Math.round(8 * z)}px] w-[${Math.min(width - 32, Math.round(440 * z))}px] p-[${Math.round(14 * z)}px] rounded-[${Math.round(8 * z)}px] bg-[#ffffff] text-[#1f1f1f] text-[${text}px] ${ink ? 'border-2 border-[#000000]' : ''}`}
        onClick={() => {}}
      >
        <span look="muted" className={`text-[${Math.round(text * 0.85)}px] ${quiet} line-clamp-3`}>{held}</span>
        <div className="flex gap-[8px]">
          <div
            look="primary"
            className={`flex-1 flex justify-center py-[${Math.round(8 * z)}px] rounded ${ink ? 'bg-[#000000]' : 'bg-[#0b57d0]'} text-[#ffffff] font-bold cursor-pointer`}
            onClick={() => open(held)}
          >
            Open
          </div>
          <a
            look="button"
            href={held}
            className={`flex-1 flex justify-center py-[${Math.round(8 * z)}px] rounded ${plainButton} cursor-pointer`}
          >
            QR code
          </a>
          <div
            look="button"
            className={`flex-1 flex justify-center py-[${Math.round(8 * z)}px] rounded ${plainButton} cursor-pointer`}
            onClick={() => (held = '')}
          >
            Cancel
          </div>
        </div>
      </div>
    </div>
  ) : null

  const round = context && context.roundBrowser
  if (round) {
    const { W, H, R, chord, top, bottom } = round
    const cap = ink ? 'bg-[#ffffff] text-[#000000]' : 'bg-[#f1f3f4] text-[#3c4043]'
    const line = ink ? 'border-[#000000]' : 'border-[#d3d6da]'
    const addressTop = Math.round(H / 2 - R * 0.86)
    const addressW = chord(R * 0.86)
    const rowTop = bottom + Math.round(4 * z)
    const rowW = chord(rowTop + bar - H / 2)
    const roundTree = (
      <div look="page" className={`relative w-[${W}px] h-[${H}px] bg-[#ffffff] text-[#1f1f1f]`}>
        <div look="bar" className={`absolute left-0 top-0 w-[${W}px] h-[${top}px] border-b ${line} ${cap}`} />
        <div look="bar" className={`absolute left-0 top-[${bottom}px] w-[${W}px] h-[${H - bottom}px] border-t ${line} ${cap}`} />
        <div className={`absolute left-[${Math.round((W - addressW) / 2)}px] top-[${addressTop}px] w-[${addressW}px] h-[${bar}px] flex items-center`}>
          {addressField}
        </div>
        <div className={`absolute left-[${Math.round((W - width) / 2)}px] top-[${top}px] w-[${width}px] h-[${bottom - top}px] flex flex-col`}>
          {pageBox}
        </div>
        <div className={`absolute left-[${Math.round((W - rowW) / 2)}px] top-[${rowTop}px] w-[${rowW}px] h-[${bar}px] flex items-center justify-center gap-[${Math.round(2 * z)}px] ${cap}`}>
          {backButton}
          {forwardButton}
          {reloadButton}
          {homeButton}
          {minusButton}
          {plusButton}
          {sourceButton}
        </div>
        {heldBox}
      </div>
    )
    if (picPending || clearing) frameos.setNextSleep(1)
    drewPage = !!showing && !source
    return roundTree
  }

  const tree = (
    <div look="page" className="flex flex-col w-full h-full bg-[#ffffff] text-[#1f1f1f]">
      <div
        look="bar"
        className={`flex items-center h-[${bar}px] shrink-0 gap-[${Math.round(2 * z)}px] px-[${Math.round(2 * z)}px] ${
          ink ? 'bg-[#ffffff] border-b border-[#000000] text-[#000000]' : 'bg-[#f1f3f4] border-b border-[#d3d6da] text-[#3c4043]'
        }`}
      >
        {backButton}
        {forwardButton}
        {reloadButton}
        {homeButton}
        {addressField}
        {minusButton}
        {plusButton}
        {sourceButton}
      </div>
      {pageBox}
      {heldBox}
    </div>
  )
  // Pictures still to come, or the page after "Loading": the next render in a second.
  if (picPending || clearing) frameos.setNextSleep(1)
  drewPage = !!showing && !source
  return tree
}

sources.html.ts:
// HTML to a page this browser can draw, in one pass over the text: a forgiving
// tokenizer feeds a tree builder that keeps only what reads (text, links,
// pictures, tables, lists, headings, GET forms) and drops the rest (scripts,
// styles, frames, video, inline SVG, hidden parts, POST forms). The builder
// never holds the document as a DOM: it keeps a stack of the open elements,
// for the cascade (css.ts) and for the HTML rules that close elements a page
// left open (a <p> before a <div>, a <td> before the next one), and writes
// the page straight into a small tree of boxes, text flows and tables that
// view.tsx turns into JSX.

import { addCss, backgroundOf, colorOf, lengthOf, matching, newSheet, parseDecls, resolveVars, sides, slimCss, type El,
  type Sheet, type Vars } from './css'
import { MAX_SVG_TEXT, parseSvg, svgAspect, type SvgEl } from './svg'

// The first of a two-value shorthand (margin-block: 8px 0).
const split1 = (v: string) => v.trim().split(/\s+(?![^(]*\))/)[0]

// A text style, interned: equal styles are one object (view.tsx keys on it).
export type St = {
  size: number // CSS px
  color: string
  bold: boolean
  italic: boolean
  under: boolean
  strike: boolean
  mono: boolean
  pre: boolean
  wrap: boolean // pre-wrap: its spaces kept, its lines wrapped
  align: string // '', 'center', 'right'
  tt: string // text-transform: '', 'u'pper, 'l'ower, 'c'apitalize
  hidden: boolean // visibility: hidden
  key: string
}
// A run of a text flow: text (with its link `a`), a line break, a picture, a
// spacer (an empty picture: Hacker News indents its comments with one), a
// field or a form's button.
export type Run =
  | { x: string; s: St; a?: string }
  | { br: true; s?: St }
  | { img: string; w: number; h: number; alt: string; a?: string }
  | { svg: string; tree?: SvgEl; w: number; h: number; a?: string } // a linked SVG (its url), or one inline (its tree)
  | { sp: true; w: number; h: number }
  | { field: number; form: number; size: number; s: St; ph: string }
  | { btn: string; form: number; s: St }
export type Flow = { k: 't'; align: string; pre: boolean; runs: Run[] }
export type Box = {
  k: 'b'
  c: Node[]
  bg?: string
  pl?: number // CSS px of left indent
  pad?: number[] // CSS px of padding: top, right, bottom
  row?: { gap: number; justify: string; wrap?: boolean } // a flex row: its children side by side (wrap: flex-wrap)
  aspect?: number // aspect-ratio: its height is its width over this
  mt?: number
  mb?: number
  w?: number // CSS px
  h?: number // CSS px, a minimum
  bar?: boolean // a blockquote's bar
  bgsvg?: string // an SVG picture it is filled with (a CSS background: Hacker News's vote arrows)
  mx?: number[] // such a picture's room to its left and right, CSS px
  mark?: string // a list item's bullet or number
  // a table cell's
  span?: number
  wpct?: number
  align?: string
  m?: any // view.tsx's measure, cached
}
export type Row = { bg?: string; h?: number; cells: Box[] }
// sp: the room between its cells (cellspacing, border-spacing), CSS px.
export type Table = { k: 'tab'; bg?: string; pad: number; sp?: number; full: boolean; border: boolean; rows: Row[]; m?: any }
export type Hr = { k: 'hr' }
export type Node = Box | Flow | Table | Hr
export type Field = { name: string; value: string; type: string }
export type Form = { action: string; fields: Field[] }
export type Page = {
  url: string
  title: string
  bg: string
  root: Box
  forms: Form[]
  svgs: string[] // the SVG pictures it links, to be downloaded
  truncated: boolean
  refresh?: string // where a <meta http-equiv="refresh"> sends it, soon
  stats: { runs: number; images: number; links: number }
}

// viewport: the width the page is laid out at, in CSS pixels (@media, srcset).
// sheetUrls: where each of `sheets` came from (its url()s are against it).
// maxSvg: the shapes of inline SVG a page may have; maxSvgFiles: the SVG
// pictures it may link.
// maxRules: the style rules kept, the page's sheets together.
// maxNest: how deep boxes go (a table's rows and cells count): every walk of
// the page is a call a level, and an ESP32's JS has 20 KB of stack. A block
// past it is a line of the box it is in.
export type Options = { maxImages?: number; maxRuns?: number; sheets?: string[]; sheetUrls?: string[]; viewport?: number;
  maxSvg?: number; maxSvgFiles?: number; maxRules?: number; maxNest?: number }

// The picture of a srcset to fetch for `width` CSS pixels: the smallest that
// is as wide (a phone's choice, not a 4K screen's), else the widest; of
// density descriptors, 1x.
export function pickSrcset(srcset: string, width: number): string {
  let best = ''
  let bestW = 0
  let widest = ''
  let widestW = -1
  for (const item of srcset.split(/,\s+/)) {
    const [url, desc] = item.trim().split(/\s+/)
    if (!url) continue
    const w = desc && desc.endsWith('w') ? parseFloat(desc) : desc && desc.endsWith('x') ? parseFloat(desc) * width : width
    if (w >= width && (!best || w < bestW)) {
      best = url
      bestW = w
    }
    if (w > widestW) {
      widest = url
      widestW = w
    }
  }
  return best || widest
}

const VOID = new Set([
  'area', 'base', 'br', 'col', 'embed', 'hr', 'img', 'input', 'link', 'meta', 'param', 'source', 'track', 'wbr',
  'keygen', 'frame', 'basefont', 'isindex',
])
// Raw text: read to their end tag without looking for tags inside.
const RAW = new Set(['script', 'style', 'textarea', 'title', 'xmp', 'iframe', 'noembed', 'noframes', 'plaintext',
  'svg'])
// Junk: dropped with everything inside.
const SKIP = new Set([
  'script', 'style', 'template', 'iframe', 'object', 'embed', 'video', 'audio', 'canvas', 'math',
  'select', 'datalist', 'map', 'noembed', 'noframes', 'frameset', 'head-skip', 'dialog', 'portal', 'slot',
])
const BLOCK = new Set([
  'address', 'article', 'aside', 'blockquote', 'center', 'dd', 'details', 'dir', 'div', 'dl', 'dt', 'fieldset',
  'figcaption', 'figure', 'footer', 'form', 'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'header', 'hgroup', 'li', 'main',
  'menu', 'nav', 'ol', 'p', 'pre', 'section', 'summary', 'ul', 'legend', 'listing', 'xmp', 'search', 'caption',
])
// What closes an open <p>.
const P_CLOSERS = new Set([
  'address', 'article', 'aside', 'blockquote', 'center', 'details', 'dir', 'div', 'dl', 'fieldset', 'figcaption',
  'figure', 'footer', 'form', 'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'header', 'hgroup', 'hr', 'main', 'menu', 'nav',
  'ol', 'p', 'pre', 'section', 'table', 'ul', 'li', 'dd', 'dt', 'search', 'listing', 'xmp',
])
// Elements whose end tag a page may leave out, and what ends them then.
const OPTIONAL_END = new Set(['li', 'p', 'td', 'th', 'tr', 'dt', 'dd'])
const CLOSES: Record<string, string[]> = {
  li: ['li'], p: [...P_CLOSERS], td: ['td', 'th', 'tr'], th: ['td', 'th', 'tr'], tr: ['tr'], dt: ['dt', 'dd'],
  dd: ['dt', 'dd'],
}
// What a skipped element of OPTIONAL_END may hold its own kind inside.
const NEST: Record<string, string[]> = {
  tr: ['table'], td: ['table'], th: ['table'], li: ['ul', 'ol', 'menu', 'dir'], dt: ['dl'], dd: ['dl'],
}
const SIZED = new Set(['img', 'table', 'td', 'th', 'tr', 'svg', 'col', 'hr', 'iframe', 'video', 'canvas', 'embed', 'object',
  'input', 'image'])
const HEADING: Record<string, number> = { h1: 2, h2: 1.5, h3: 1.17, h4: 1, h5: 0.83, h6: 0.67 }
const FONT_SIZES = [0, 10, 13, 16, 18, 24, 32, 48]
// Vertical margins, in em of the element's own size.
const MARGIN: Record<string, number> = {
  p: 1, h1: 0.67, h2: 0.83, h3: 1, h4: 1.33, h5: 1.67, h6: 2.33, ul: 1, ol: 1, dl: 1, blockquote: 1, pre: 1,
  figure: 1, menu: 1, dir: 1, hr: 0.5, fieldset: 0.5,
}
const ENTITIES: Record<string, string> = {
  amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ', copy: '©', reg: '®', trade: '™', mdash: '—',
  ndash: '–', hellip: '…', laquo: '«', raquo: '»', lsquo: '‘', rsquo: '’', ldquo: '“', rdquo: '”', sbquo: '‚',
  bdquo: '„', bull: '•', middot: '·', times: '×', divide: '÷', euro: '€', pound: '£', yen: '¥', cent: '¢',
  sect: '§', para: '¶', deg: '°', plusmn: '±', frac12: '½', frac14: '¼', frac34: '¾', sup2: '²', sup3: '³',
  larr: '←', rarr: '→', uarr: '↑', darr: '↓', harr: '↔', lArr: '⇐', rArr: '⇒', hearts: '♥', thinsp: ' ',
  ensp: ' ', emsp: ' ', zwnj: '', zwj: '', shy: '', lrm: '', rlm: '', iexcl: '¡', iquest: '¿',
  auml: 'ä', ouml: 'ö', uuml: 'ü', Auml: 'Ä', Ouml: 'Ö', Uuml: 'Ü', szlig: 'ß', eacute: 'é', egrave: 'è',
  ecirc: 'ê', aacute: 'á', agrave: 'à', acirc: 'â', iacute: 'í', oacute: 'ó', uacute: 'ú', ntilde: 'ñ',
  ccedil: 'ç', aring: 'å', oslash: 'ø', aelig: 'æ', Eacute: 'É', prime: '′', Prime: '″', minus: '−', le: '≤',
  ge: '≥', ne: '≠', infin: '∞', check: '✓', star: '☆',
}

export function decode(text: string): string {
  if (text.indexOf('&') < 0) return text
  return text.replace(/&(#[xX][0-9a-fA-F]{1,6}|#[0-9]{1,7}|[a-zA-Z][a-zA-Z0-9]{1,31})(;?)/g, (all, name, semi) => {
    if (name[0] === '#') {
      const code = name[1] === 'x' || name[1] === 'X' ? parseInt(name.slice(2), 16) : parseInt(name.slice(1), 10)
      if (!(code > 0) || code > 0x10ffff || (code >= 0xd800 && code <= 0xdfff)) return '�'
      return String.fromCodePoint(code === 0xa0 ? 0xa0 : code)
    }
    const value = ENTITIES[name]
    if (value === undefined) return all
    // Without a ";" only the old ones, as browsers read them.
    if (!semi && !/^(amp|lt|gt|quot|nbsp|copy|reg)$/.test(name)) return all
    return value
  })
}

// A URL against the page's, or '' for one this browser does not open.
export function resolve(href: string, base: string): string {
  const h = href.trim().replace(/[\t\n\r]/g, '')
  if (!h || h[0] === '#') return ''
  if (/^(https?:|mailto:|tel:)/i.test(h)) return h
  if (/^[a-z][a-z0-9+.-]*:/i.test(h)) return '' // javascript:, data:, ...
  const m = /^(https?:)\/\/([^/?#]*)([^?#]*)(\?[^#]*)?/i.exec(base)
  if (!m) return ''
  const [, scheme, host] = m
  const basePath = m[3] || '/'
  if (h.startsWith('//')) return scheme + h
  if (h[0] === '/') return scheme + '//' + host + normalizePath(h)
  if (h[0] === '?') return scheme + '//' + host + basePath + h
  const dir = basePath.slice(0, basePath.lastIndexOf('/') + 1)
  return scheme + '//' + host + normalizePath(dir + h)
}

function normalizePath(path: string): string {
  const q = path.search(/[?#]/)
  const p = q < 0 ? path : path.slice(0, q)
  const rest = q < 0 ? '' : path.slice(q)
  const out: string[] = []
  const parts = p.split('/')
  for (let i = 0; i < parts.length; i++) {
    const part = parts[i]
    if (part === '..') {
      if (out.length > 1) out.pop()
    } else if (part !== '.') out.push(part)
  }
  const last = parts[parts.length - 1]
  if ((last === '.' || last === '..') && out[out.length - 1] !== '') out.push('')
  return out.join('/') + rest
}

// What a style sheet's name says it holds: the page's look (main, style,
// site, theme) before fonts, icons, code colors and widgets.
const SHEET_MAIN = /(^|[\/._-])(main|style|styles|site|theme|app|global|base|screen|common|index|bundle|layout|core)([._-]|$)/i
const SHEET_AUX = /(font|icon|gist|code|syntax|highlight|prism|katex|mathjax|emoji|vendor|cookie|consent|plugin|widget|button|pagination|comment|search|share|social|slider|carousel|swiper|lightbox|animate)/i
// Another look of the same page (a dark or high-contrast theme, print, right to left).
const SHEET_OTHER = /(print|dark|contrast|colorblind|tritanopia|deuteranopia|protanopia|dimmed|rtl)/i

// The stylesheets a page links (the `max` that look most like its own look,
// then fonts, icons, code and the like, in the page's order; print and the
// page's other themes, dark or high contrast, only when it has next to no
// others), and its <base href>.
export function scanHead(html: string, url: string, max = 3): { base: string; sheets: string[] } {
  const head = html.slice(0, 200000)
  let base = url
  const b = /<base\s[^>]*href\s*=\s*["']?([^"' >]+)/i.exec(head)
  if (b) base = resolve(decode(b[1]), url) || url
  const found: { url: string; rank: number; at: number }[] = []
  const re = /<link\s[^>]*>/gi
  let m: RegExpExecArray | null
  while ((m = re.exec(head)) && found.length < 60) {
    const tag = m[0]
    if (!/rel\s*=\s*["']?[^"'>]*\bstylesheet\b/i.test(tag)) continue
    if (/media\s*=\s*["']?(print|speech)/i.test(tag) || /\balternate\b/i.test(tag)) continue
    const href = /\shref\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))/i.exec(tag)
    const abs = href ? resolve(decode(href[1] ?? href[2] ?? href[3] ?? ''), base) : ''
    if (!abs || !/^https?:/i.test(abs)) continue
    const path = abs.replace(/[?#].*$/, '').replace(/^https?:\/\/[^/]*/i, '')
    const rank = SHEET_OTHER.test(path) ? -1 : SHEET_MAIN.test(path.replace(/^.*\//, '')) ? 2 : SHEET_AUX.test(path) ? 0 : 1
    if (!found.some((f) => f.url === abs)) found.push({ url: abs, rank, at: found.length })
  }
  const own = found.filter((f) => f.rank > 0).length
  const chosen = found.filter((f) => f.rank >= 0 || own < 2).sort((x, y) => y.rank - x.rank || x.at - y.at).slice(0, max)
  chosen.sort((x, y) => x.at - y.at)
  return { base, sheets: chosen.map((c) => c.url) }
}

// --- A page read in pieces, kept slim.
//
// A news site's home page is several megabytes, most of it scripts and style
// sheets in the page itself (and its first words megabytes in): more than a
// frame holds, and far more than this browser draws. The slimmer reads the
// page as it comes, a piece at a time (app.tsx asks for it in byte ranges
// where the server answers them), and keeps what reads: the markup, the text,
// the first of the page's <style>s up to `css` characters, and SVG small
// enough to draw. Scripts, comments, big SVG and <template>s go as they pass,
// so what is kept is a few hundred kilobytes wherever the page's own words
// start. A tag cut where one piece ends is finished with the next.

export type Slim = {
  out: string[] // what is kept, in pieces
  size: number // its length
  carry: string // the end of the last piece, not yet read (a tag cut in two)
  raw: string // inside this element (script, style, svg, ...) until its end tag
  keep: boolean // whether what is inside it is kept
  css: number // the room left for style sheets, in characters (slimmed: slimCss)
  width: number // the width the page is laid out at, for the sheets' @media
  style: string // a <style>'s text not yet slimmed (its last rule not in yet)
  depth: number // how deep in braces that text ends
  scan: number // how much of it was looked at for them
  ended: boolean // </html> was seen, or there is no more room
}

export const MAX_SLIM_SVG = 16 * 1024
// A tag to its ">", quoted values whole; braces and comments in a style sheet.
const TAG = /<[^>"']*(?:(?:"[^"]*"|'[^']*')[^>"']*)*>/y
const BRACES = /[{}]|\/\*/g
const SLIM_RAW = new Set(['script', 'style', 'svg', 'template', 'textarea', 'title', 'xmp', 'noembed', 'noframes', 'iframe'])

export function slimmer(css = 512 * 1024, width = 640): Slim {
  return { out: [], size: 0, carry: '', raw: '', keep: true, css, width, style: '', depth: 0, scan: 0, ended: false }
}

const keep = (s: Slim, text: string) => {
  if (!text) return
  s.out.push(text)
  s.size += text.length
}

// Reads the next piece of the page (`last`: there is no more), keeping at most
// `room` characters in all.
export function slimPush(s: Slim, piece: string, last: boolean, room = Infinity) {
  if (s.ended) return
  const text = s.carry + piece
  s.carry = ''
  const n = text.length
  let i = 0
  // What is inside a raw element, kept if it is kept: a style sheet while
  // there is room for it, cut (and closed) where there is none.
  const keepRaw = (part: string, end: string) => {
    if (!s.keep) return
    if (s.raw === 'style') {
      // Slimmed a whole rule at a time (slimCss), as the rules come.
      s.style += part
      let depth = s.depth
      let cut = -1
      BRACES.lastIndex = s.scan
      let b: RegExpExecArray | null
      while ((b = BRACES.exec(s.style))) {
        if (b[0] === '{') depth++
        else if (b[0] === '}') {
          if (depth > 0 && --depth === 0) cut = b.index + 1
        } else {
          const e = s.style.indexOf('*/', b.index + 2)
          if (e < 0) {
            BRACES.lastIndex = b.index
            break
          }
          BRACES.lastIndex = e + 2
        }
        s.scan = BRACES.lastIndex
      }
      if (!b) s.scan = s.style.length
      s.depth = depth
      const whole = end ? s.style.length : cut
      if (whole > 0) {
        const css = slimCss(s.style.slice(0, whole), s.width)
        s.style = s.style.slice(whole)
        s.scan = Math.max(0, s.scan - whole)
        if (css.length > s.css) {
          keep(s, css.slice(0, Math.max(0, css.lastIndexOf('}', s.css) + 1)) + '</style>')
          s.css = 0
          s.keep = false
          return
        }
        s.css -= css.length
        keep(s, css)
      }
      if (s.style.length > 1024 * 1024) s.style = '' // a rule a megabyte long: none
      if (end) {
        s.style = ''
        s.depth = s.scan = 0
        keep(s, end)
      }
      return
    }
    keep(s, part + end)
  }
  // An element whose text is raw is read to its end tag, kept or not.
  const closeRaw = (): boolean => {
    const re = new RegExp('</' + s.raw + '\\s*>', 'ig')
    re.lastIndex = i
    const m = re.exec(text)
    if (!m) {
      // Not ended in this piece: what is kept goes now, a few letters stay
      // back in case the end tag is cut in two.
      const stay = last ? n : Math.max(i, n - s.raw.length - 3)
      keepRaw(text.slice(i, stay), '')
      i = stay
      return false
    }
    keepRaw(text.slice(i, m.index), m[0])
    i = m.index + m[0].length
    s.raw = ''
    return true
  }
  if (s.raw && !closeRaw()) {
    s.carry = text.slice(i)
    return
  }
  while (i < n) {
    if (s.size >= room) {
      s.ended = true
      return
    }
    const lt = text.indexOf('<', i)
    if (lt < 0) {
      keep(s, text.slice(i))
      i = n
      break
    }
    keep(s, text.slice(i, lt))
    i = lt
    if (text.startsWith('<!--', i)) {
      const end = text.indexOf('-->', i + 4)
      if (end < 0) {
        if (!last) s.carry = text.slice(i)
        return
      }
      i = end + 3
      continue
    }
    // The tag, to its ">" (one in quotes does not end it); a stray quote
    // (an apostrophe in a bare value) does not hold it open past the next
    // tag.
    TAG.lastIndex = i
    const t = TAG.exec(text)
    let j = t ? i + t[0].length - 1 : -1
    const plain = text.indexOf('>', i)
    if (plain >= 0 && (j < 0 || (j > plain && text.indexOf('<', i + 1) < j && text.indexOf('<', i + 1) >= 0))) j = plain
    if (j < 0) j = n
    if (j >= n) {
      if (!last) s.carry = text.slice(i)
      else keep(s, text.slice(i))
      return
    }
    const tag = text.slice(i, j + 1)
    i = j + 1
    const m = /^<(\/?)([a-zA-Z][\w:-]*)/.exec(tag)
    const name = m ? m[2].toLowerCase() : ''
    if (m && m[1]) {
      keep(s, tag)
      if (name === 'html') {
        s.ended = true
        return
      }
      continue
    }
    if (name === 'source' || name === 'link' && !/stylesheet/i.test(tag)) continue // a <picture>'s other files: its <img> is the one drawn
    if (!SLIM_RAW.has(name) || tag.endsWith('/>')) {
      keep(s, tag.length > 100 ? slimTag(tag) : tag)
      continue
    }
    // A raw element: a script goes, a style is kept while there is room, an
    // SVG if it is small; the rest are kept.
    let kept = true
    if (name === 'script' || name === 'template') kept = false
    else if (name === 'style') kept = s.css > 0
    else if (name === 'svg') {
      const end = text.indexOf('</svg', i)
      kept = end < 0 ? !last && n - i < MAX_SLIM_SVG : end - i < MAX_SLIM_SVG
      if (end < 0 && !last && kept) {
        // Read with the next piece, whole.
        s.carry = text.slice(i - tag.length)
        return
      }
    }
    s.raw = name
    s.keep = kept
    if (kept) keep(s, tag)
    if (!closeRaw()) {
      s.carry = text.slice(i)
      return
    }
  }
}

// Attributes read here (or by a style sheet's selector, short ones): a long
// value of any other (a component's JSON props, analytics data) goes.
const SLIM_KEEP = /^(href|src|srcset|data-src|data-srcset|data-lazy-src|style|class|alt|content|action|value|placeholder|sizes|title)$/i

function slimTag(tag: string): string {
  return tag.replace(/(\s)([^\s=>"'/]+)\s*=\s*("[^"]*"|'[^']*'|[^\s>"']+)/g, (all, sp, name, value) =>
    (value.length > 40 && !SLIM_KEEP.test(name)) || /^on/i.test(name) ? sp + name : all)
}

// What was kept, as one text.
export function slimText(s: Slim): string {
  const text = s.out.join('') + (s.ended ? '' : s.carry)
  s.out = [text]
  return text
}

// WCAG's contrast ratio of two #rrggbb colors (1 to 21).
function contrast(a: string, b: string): number {
  const lum = (c: string) => {
    const m = /^#([0-9a-f]{2})([0-9a-f]{2})([0-9a-f]{2})$/i.exec(c)
    if (!m) return -1
    const ch = (h: string) => {
      const v = parseInt(h, 16) / 255
      return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4)
    }
    return 0.2126 * ch(m[1]) + 0.7152 * ch(m[2]) + 0.0722 * ch(m[3])
  }
  const x = lum(a)
  const y = lum(b)
  if (x < 0 || y < 0) return 21
  return (Math.max(x, y) + 0.05) / (Math.min(x, y) + 0.05)
}

type Kind = 'box' | 'table' | 'row' | 'inline' | 'form'
type Entry = {
  tag: string
  el: El
  st: St
  kind: Kind
  node?: Box | Table | Row
  flow?: Flow | null // a box's text flow still open
  href?: string
  form?: number // the GET form this is in, or -1 in a POST one
  list?: { ordered: boolean; n: number; none: boolean }
  btn?: { btn: string; form: number; s: St }
  apart?: boolean // an inline element with room after it (margin-right): words end there
  shut?: boolean // a <details> not open: its <summary> alone shows
  items?: boolean // a flex box or a grid: its children are blocks
  inl?: boolean // an inline-flex or inline-grid: its children are inline, in its line
  flat?: boolean // a block past maxNest: no box, its own lines
  ground?: string // the color it is drawn on (its own background, or the nearest one under it)
  vars: Vars // custom properties, its parent's underneath
}

const BASE_STYLE = { size: 16, color: '#000000', bold: false, italic: false, under: false, strike: false, mono: false,
  pre: false, wrap: false, align: '', tt: '', hidden: false }

export function convert(html: string, url: string, options: Options = {}): Page {
  const maxImages = options.maxImages ?? 40
  const maxRuns = options.maxRuns ?? 30000
  const maxNest = options.maxNest ?? 200
  const viewport = options.viewport ?? 640
  // No doctype: quirks mode, where a class or an id matches in any case.
  const quirks = !/<!doctype\s/i.test(html.slice(0, 2048))
  const fold = (name: string) => (quirks ? name.toLowerCase() : name)
  const classes = (text: string | undefined) => (text ? fold(text).trim().split(/\s+/) : [])
  const sheet: Sheet = newSheet(viewport, quirks, options.maxRules)
  const { base } = scanHead(html, url)
  // What the page's collapsed controls open (a menu's button, aria-expanded
  // "false"): closed until a script opens it.
  const collapsed = new Set<string>()
  const ctl = /<[a-z][^>]*\saria-expanded\s*=\s*["']?false[^>]*>/gi
  let cm: RegExpExecArray | null
  while ((cm = ctl.exec(html)) && collapsed.size < 200) {
    const ids = /\saria-controls\s*=\s*["']?([^"'>]+)/i.exec(cm[0])
    if (ids) for (const id of ids[1].trim().split(/\s+/)) collapsed.add(fold(id))
  }
  ;(options.sheets || []).forEach((css, i) => {
    const from = (options.sheetUrls || [])[i] || base
    addCss(sheet, css, (ref) => resolve(decode(ref), from))
  })
  let svgBudget = options.maxSvg ?? 4000
  const maxSvgFiles = options.maxSvgFiles ?? 6

  const styles = new Map<string, St>()
  const intern = (s: Omit<St, 'key'>): St => {
    const key = `${Math.round(s.size * 10) / 10}|${s.color}|${+s.bold}${+s.italic}${+s.under}${+s.strike}${+s.mono}${+s.pre}${+s.wrap}${+s.hidden}|${s.align}|${s.tt}`
    let st = styles.get(key)
    if (!st) styles.set(key, (st = { ...s, size: Math.round(s.size * 10) / 10, key }))
    return st
  }

  const root: Box = { k: 'b', c: [] }
  const page: Page = { url, title: '', bg: '', root, forms: [], svgs: [], truncated: false, stats: { runs: 0, images: 0, links: 0 } }
  // A linked SVG picture: listed to be downloaded, if there is room for it.
  const svgFile = (abs: string) => {
    if (page.svgs.indexOf(abs) >= 0) return true
    if (page.svgs.length >= maxSvgFiles) return false
    page.svgs.push(abs)
    return true
  }
  const stack: Entry[] = [
    { tag: 'html', el: { tag: 'html', id: '', cls: [], link: false }, st: intern(BASE_STYLE), kind: 'box', node: root, flow: null, form: undefined,
      vars: {} },
  ]
  const els: El[] = [stack[0].el]
  let htmlAttrs: Record<string, string> = {}
  const rootEntry = stack[0]
  // The <html> element's style (`:root`), over the browser's.
  const styleRoot = () => {
    const el: El = { tag: 'html', id: fold(htmlAttrs.id || ''), cls: classes(htmlAttrs.class), link: false,
      attrs: htmlAttrs }
    els.length = 1
    els[0] = el
    const look = styleFor("html", htmlAttrs, { ...rootEntry, st: intern(BASE_STYLE), vars: {} })
    stack[0].el = el
    stack[0].st = look.st
    stack[0].vars = look.vars
    if (look.bg) page.bg = look.bg
  }
  let runs = 0

  const top = () => stack[stack.length - 1]
  const push = (e: Entry) => {
    stack.push(e)
    els.push(e.el)
  }
  const popTo = (i: number) => {
    // Pops entries i.. off the stack.
    while (stack.length > i && stack.length > 1) {
      stack.pop()
      els.pop()
    }
  }
  const find = (pred: (e: Entry) => boolean, stop?: (e: Entry) => boolean): number => {
    for (let i = stack.length - 1; i > 0; i--) {
      if (pred(stack[i])) return i
      if (stop && stop(stack[i])) return -1
    }
    return -1
  }
  const tableScope = (e: Entry) => e.kind === 'table' || e.kind === 'row' || e.tag === 'td' || e.tag === 'th'
  const formOf = (): number | undefined => {
    for (let i = stack.length - 1; i >= 0; i--) if (stack[i].form !== undefined) return stack[i].form
    return undefined
  }
  // The link text is in; a link around a block (<a><div>…</div></a>) still
  // links what is in it.
  const hrefOf = (): string => {
    for (let i = stack.length - 1; i > 0; i--) if (stack[i].href !== undefined) return stack[i].href as string
    return ''
  }

  // The box that text and inline things go into: the nearest open box, or a
  // cell made for them where a table holds them directly.
  const sinkEntry = (): Entry => {
    for (let i = stack.length - 1; i >= 0; i--) {
      const e = stack[i]
      if (e.kind === 'box') return e
      if (e.kind === 'table' || e.kind === 'row') {
        popTo(i + 1)
        if (e.kind === 'table') openRow(e, {}, e.st)
        return openCell(top(), 'td', {}, top().st, true)
      }
    }
    return stack[0]
  }
  const flowOf = (e: Entry): Flow => {
    if (!e.flow) {
      e.flow = { k: 't', align: e.st.align, pre: e.st.pre, runs: [] }
      ;(e.node as Box).c.push(e.flow)
    }
    return e.flow
  }
  const endFlow = () => {
    for (let i = stack.length - 1; i >= 0; i--) {
      if (stack[i].kind === 'box') {
        stack[i].flow = null
        return
      }
    }
  }
  const nest = () => {
    let n = 0
    for (const e of stack) if (e.kind === 'box' || e.kind === 'table' || e.kind === 'row') n++
    return n
  }
  const addRun = (run: Run) => {
    if (runs >= maxRuns) {
      page.truncated = true
      return
    }
    runs++
    flowOf(sinkEntry()).runs.push(run)
  }

  const text = (raw: string) => {
    const t = top()
    if (t.shut) return
    if (t.btn) {
      t.btn.btn = (t.btn.btn + decode(raw)).replace(/\s+/g, ' ')
      return
    }
    let s = decode(raw)
    if (!t.st.pre) {
      s = s.replace(/[ \t\n\r\f]+/g, ' ')
      if (s === ' ') {
        // White space alone between table parts is nothing.
        if (t.kind === 'table' || t.kind === 'row') return
      }
    } else {
      s = s.replace(/\r\n?/g, '\n')
    }
    if (!s || t.st.hidden) return
    const e = sinkEntry()
    const flow = flowOf(e)
    const last = flow.runs[flow.runs.length - 1] as any
    if (!t.st.pre && s[0] === ' ' && (!last || last.br || (last.x !== undefined && last.x.endsWith(' ')))) {
      s = s.slice(1)
      if (!s) return
    }
    if (t.st.pre && !last && s[0] === '\n') s = s.slice(1)
    if (t.st.tt === 'u') s = s.toUpperCase()
    else if (t.st.tt === 'l') s = s.toLowerCase()
    else if (t.st.tt === 'c') s = s.replace(/(^|\s)(\S)/g, (all, sp, c) => sp + c.toUpperCase())
    const href = hrefOf()
    if (last && last.x !== undefined && last.s === t.st && (last.a || '') === href) {
      last.x += s
      return
    }
    const run: any = { x: s, s: t.st }
    if (href) {
      run.a = href
      page.stats.links++
    }
    addRun(run)
  }

  // The style an element gets: its parent's, the tag's own, its attributes,
  // the stylesheets' rules, then its style attribute.
  const styleFor = (tag: string, attrs: Record<string, string>, parent: Entry) => {
    const s: Omit<St, 'key'> = { ...parent.st }
    let bg = ''
    let display = BLOCK.has(tag) ? 'block' : ''
    let width = NaN
    let height = NaN
    let apart = 0 // bit 1: room before it, bit 2: after it
    switch (tag) {
      case 'b':
      case 'strong':
      case 'th':
        s.bold = true
        break
      case 'i':
      case 'em':
      case 'cite':
      case 'var':
      case 'dfn':
      case 'address':
        s.italic = true
        break
      case 'u':
      case 'ins':
        s.under = true
        break
      case 's':
      case 'strike':
      case 'del':
        s.strike = true
        break
      case 'code':
      case 'kbd':
      case 'samp':
      case 'tt':
        s.mono = true
        break
      case 'pre':
      case 'xmp':
      case 'listing':
        s.mono = true
        s.pre = true
        s.wrap = false
        break
      case 'small':
        s.size = parent.st.size / 1.2
        break
      case 'big':
        s.size = parent.st.size * 1.2
        break
      case 'sub':
      case 'sup':
        s.size = parent.st.size * 0.83
        break
      case 'center':
        s.align = 'center'
        break
      case 'a':
        if (attrs.href !== undefined) {
          s.color = '#0000ee'
          s.under = true
        }
        break
    }
    if (HEADING[tag]) {
      s.size = 16 * HEADING[tag] * (parent.st.size / 16)
      s.bold = true
    }
    if (tag === 'th') s.align = 'center'
    if (tag === 'font') {
      const c = colorOf(attrs.color)
      if (c) s.color = c
      const size = (attrs.size || '').trim()
      if (size) {
        let n = parseInt(size, 10)
        if (size[0] === '+' || size[0] === '-') n = 3 + n
        if (n > 0) s.size = FONT_SIZES[Math.min(7, Math.max(1, n))]
      }
    }
    if (attrs.align && /^(p|div|h[1-6]|td|th|tr|caption|center)$/.test(tag)) {
      const a = attrs.align.toLowerCase()
      s.align = a === 'center' || a === 'middle' ? 'center' : a === 'right' ? 'right' : a === 'left' ? '' : s.align
    }
    if (attrs.bgcolor) bg = colorOf(attrs.bgcolor)
    if (attrs.text && tag === 'body') s.color = colorOf(attrs.text) || s.color
    // Hidden until a script shows it: `hidden`, a popover, what a collapsed
    // control (aria-expanded="false") says it opens.
    if (attrs.hidden !== undefined || attrs.popover !== undefined || (attrs.id && collapsed.has(fold(attrs.id)))) display = 'none'
    // The width and height attributes of the elements that have them (a
    // <div width="300"> is a script's, not the page's look).
    const sized = SIZED.has(tag)
    if (sized && attrs.width && /^\d+%$/.test(attrs.width.trim())) width = -parseInt(attrs.width, 10)
    else if (sized && attrs.width && /^\d+(px)?$/.test(attrs.width.trim())) width = parseInt(attrs.width, 10)
    if (sized && attrs.height && /^\d+(px)?$/.test(attrs.height.trim())) height = parseInt(attrs.height, 10)

    // Custom properties first (they cascade and inherit), then the rest with
    // their var()s worked out against them.
    const decls = matching(sheet, els)
    if (attrs.style) decls.push(parseDecls(attrs.style))
    let vars = parent.vars
    for (const d of decls) {
      for (const name in d) {
        if (name.charCodeAt(0) !== 45 || name.charCodeAt(1) !== 45) continue
        if (vars === parent.vars) vars = Object.create(parent.vars)
        vars[name] = d[name]
      }
    }
    const ps = parent.st
    let pad = [NaN, NaN, NaN, NaN]
    let mt = NaN
    let mb = NaN
    let ml = NaN
    let mr = NaN
    let off = 0 // placed off the page (a skip link above it, a menu slid out to its left)
    let spacing = NaN
    let listNone = false
    let srOnly = 0
    let fixed = 0 // position: fixed (1), anchored to the bottom (2) or covering the screen (4)
    let faded = false // opacity: 0
    let flex = false
    let grid = false
    let inl = false
    let wraps = false
    let column = false
    let gap = NaN
    let justify = ''
    let aspect = 0
    let cover = false
    let bgsvg = ''
    const value = (d: Record<string, string>, name: string) => {
      const v = d[name]
      return v === undefined ? undefined : v.indexOf('var(') >= 0 ? resolveVars(v, vars).trim() : v
    }
    const inherits = (v: string) => v === 'inherit' || v === 'unset'
    const apply = (d: Record<string, string>) => {
      let v = value(d, 'color')
      if (v) s.color = inherits(v) || v === 'currentcolor' ? ps.color : v === 'initial' ? '#000000' : colorOf(v) || s.color
      const b = backgroundOf(value(d, 'background-color') || value(d, 'background'))
      if (b) bg = b === 'transparent' ? '' : b
      if ((v = value(d, 'background-image') || value(d, 'background'))) {
        const u = /url\(\s*["']?(https?:[^"')]+?\.svg(?:[?#][^"')]*)?)["']?\s*\)/i.exec(v)
        bgsvg = u ? u[1] : /url\(|none/.test(v) ? '' : bgsvg
      }
      if ((v = value(d, 'font-size'))) {
        const n = inherits(v) ? ps.size : lengthOf(v, ps.size)
        if (n > 0) s.size = n
      }
      if ((v = value(d, 'font'))) {
        const m = /(^|\s)([\d.]+(?:px|pt|em|rem|%))/.exec(v)
        if (m) {
          const n = lengthOf(m[2], ps.size)
          if (n > 0) s.size = n
        }
        if (/\b(bold|[6-9]00)\b/.test(v)) s.bold = true
        if (/\bmonospace\b/.test(v)) s.mono = true
      }
      if ((v = value(d, 'font-weight'))) {
        s.bold = inherits(v) ? ps.bold : v === 'bold' || v === 'bolder' || parseInt(v, 10) >= 600
      }
      if ((v = value(d, 'font-style'))) s.italic = inherits(v) ? ps.italic : /italic|oblique/.test(v)
      if ((v = value(d, 'font-family'))) {
        s.mono = inherits(v) ? ps.mono : /monospace|courier|consolas|menlo|mono\b/i.test(v.split(',')[0])
      }
      if ((v = value(d, 'text-decoration-line') || value(d, 'text-decoration'))) {
        s.under = inherits(v) ? ps.under : /underline/.test(v)
        s.strike = inherits(v) ? ps.strike : /line-through/.test(v)
      }
      if ((v = value(d, 'text-align'))) {
        s.align = inherits(v) ? ps.align : v === 'center' ? 'center' : v === 'right' || v === 'end' ? 'right' : ''
      }
      if ((v = value(d, 'text-transform'))) {
        s.tt = inherits(v) ? ps.tt : v === 'uppercase' ? 'u' : v === 'lowercase' ? 'l' : v === 'capitalize' ? 'c' : ''
      }
      if ((v = value(d, 'display'))) {
        flex = v === 'flex'
        grid = v === 'grid'
        inl = v === 'inline-flex' || v === 'inline-grid'
        if (v === 'none') display = 'none'
        else if (/^(block|flex|grid|list-item|flow-root|table)$/.test(v)) display = 'block'
        else if (/^(inline|inline-block|inline-flex|inline-grid|contents)$/.test(v)) display = ''
      }
      if ((v = value(d, 'flex-direction') || value(d, 'flex-flow'))) column = /column/.test(v)
      if ((v = value(d, 'flex-wrap') || value(d, 'flex-flow'))) wraps = /\bwrap/.test(v) && !/nowrap/.test(v)
      if ((v = value(d, 'gap') || value(d, 'column-gap'))) gap = lengthOf(v.split(/\s+/).pop(), s.size)
      if ((v = value(d, 'justify-content'))) {
        justify = /between|around|evenly/.test(v) ? 'between' : /center/.test(v) ? 'center' : /end|right/.test(v) ? 'end' : ''
      }
      if ((v = value(d, 'aspect-ratio'))) {
        const m = /^([\d.]+)\s*(?:\/\s*([\d.]+))?/.exec(v)
        aspect = m ? parseFloat(m[1]) / (m[2] ? parseFloat(m[2]) : 1) : 0
      }
      if ((v = value(d, 'object-fit'))) cover = v === 'cover'
      if ((v = value(d, 'visibility'))) s.hidden = v === 'hidden' || v === 'collapse'
      if ((v = value(d, 'white-space'))) {
        s.pre = /^pre|break-spaces/.test(v)
        s.wrap = /pre-wrap|pre-line|break-spaces/.test(v)
      }
      if ((v = value(d, 'width'))) {
        // A share of the box it is in, or a sum with one (calc(100% - 2rem)):
        // never of the font size.
        if (/^[\d.]+%$/.test(v)) width = -parseFloat(v)
        else if (v.indexOf('%') >= 0) width = /^calc\(\s*100%/.test(v) ? -100 : NaN
        else {
          const n = lengthOf(v, s.size)
          width = n >= 0 ? n : NaN
        }
      }
      if ((v = value(d, 'height'))) {
        const n = v.indexOf('%') >= 0 ? NaN : lengthOf(v, s.size)
        height = n >= 0 ? n : NaN
      }
      if ((v = value(d, 'list-style') || value(d, 'list-style-type'))) listNone = /\bnone\b/.test(v)
      // Text kept for screen readers alone (Tailwind's sr-only): clipped away.
      if ((v = value(d, 'clip')) && /rect\(0/.test(v)) srOnly |= 1
      if ((v = value(d, 'clip-path')) && /inset\(50%\)/.test(v)) srOnly |= 1
      if ((v = value(d, 'position'))) {
        srOnly = /absolute|fixed/.test(v) ? srOnly | 2 : srOnly & ~2
        fixed = v === 'fixed' ? fixed | 1 : fixed & ~1
      }
      if ((v = value(d, 'bottom'))) fixed = v !== 'auto' && lengthOf(v, s.size) < 200 ? fixed | 2 : fixed & ~2
      if ((v = value(d, 'inset')) && /^0(px)?(\s|$)/.test(v.trim())) fixed |= 4
      if ((v = value(d, 'height')) && /^100(vh|dvh|svh|lvh|%)$/.test(v.trim())) fixed |= 4
      if ((v = value(d, 'opacity'))) faded = parseFloat(v) === 0
      // Padding and the top margin, in CSS pixels.
      if ((v = value(d, 'padding'))) pad = sides(v, s.size)
      if ((v = value(d, 'padding-block'))) pad[0] = pad[2] = sides(v, s.size)[0]
      if ((v = value(d, 'padding-inline'))) pad[1] = pad[3] = sides(v, s.size)[1]
      for (const [name, side] of [['padding-top', 0], ['padding-right', 1], ['padding-bottom', 2], ['padding-left', 3],
        ['padding-inline-start', 3], ['padding-inline-end', 1]] as [string, number][]) {
        if ((v = value(d, name))) pad[side] = lengthOf(v, s.size)
      }
      if ((v = value(d, 'margin'))) {
        const m = sides(v, s.size)
        mt = m[0]
        mb = m[2]
        mr = m[1]
        ml = m[3]
      }
      if ((v = value(d, 'margin-left') || value(d, 'margin-inline-start'))) ml = lengthOf(v, s.size)
      if ((v = value(d, 'margin-right') || value(d, 'margin-inline-end'))) mr = lengthOf(v, s.size)
      if ((v = value(d, 'margin-block'))) {
        const m = sides(v, s.size)
        mt = m[0]
        mb = m[2]
      }
      if ((v = value(d, 'margin-block-start') || value(d, 'margin-top'))) mt = lengthOf(split1(v), s.size)
      if ((v = value(d, 'margin-block-end') || value(d, 'margin-bottom'))) mb = lengthOf(split1(v), s.size)
      for (let side = 0; side < 2; side++) {
        if ((v = value(d, side ? 'left' : 'top'))) {
          const far = v[0] === '-' && (/%$/.test(v) ? parseFloat(v) <= -50 : lengthOf(v, s.size) <= -30)
          off = far ? off | (1 << side) : off & ~(1 << side)
        }
      }
      if ((v = value(d, 'transform') || value(d, 'translate'))) {
        off = /^(translate[xy3d]*\()?\s*-(\d{3,}|[5-9]\d)(\.\d*)?%/i.test(v) ? off | 4 : off & ~4
      }
      if ((v = value(d, 'border-collapse'))) spacing = v === 'collapse' ? 0 : spacing
      if ((v = value(d, 'border-spacing'))) spacing = lengthOf(split1(v), s.size)
    }
    for (const d of decls) apply(d)
    // Room at its sides (a margin, a padding): an inline element's words end
    // there (links side by side, a margin apart).
    if (ml >= 3 || pad[3] >= 3) apart |= 1
    if (mr >= 3 || pad[1] >= 3) apart |= 2
    // Words the color of what they are on (a dark header whose light text
    // color is in a sheet or a theme not read here): the one that reads.
    const ground = bg || parent.ground || page.bg || '#ffffff'
    if (contrast(s.color, ground) < 1.4) s.color = contrast('#000000', ground) > contrast('#ffffff', ground) ? '#000000' : '#ffffff'
    if (srOnly === 3 || (srOnly & 2 && ((width >= 0 && width <= 1 && height >= 0 && height <= 1) || off))) display = 'none'
    // Placed over the page and not seen (a menu not open, a fading slide), or
    // laid over it where scripts would take it away again (a cookie banner
    // along the bottom, a dialog over everything): not this page's words.
    if (srOnly & 2 && (s.hidden || faded)) display = 'none'
    if (fixed & 1 && fixed & 6) display = 'none'
    const row = flex && !column ? { gap: gap >= 0 ? Math.min(gap, 64) : 0, justify, ...(wraps ? { wrap: true } : {}) } : null
    return { st: intern(s), bg, ground, bgsvg, display, items: (flex || grid) && display === 'block', inl: inl && display !== 'block', width, height, pad, mt, mb, ml, mr, spacing, listNone, apart, vars, row, abs: (srOnly & 2) !== 0,
      aspect: aspect > 0.1 && aspect < 10 ? aspect : 0, cover }
  }

  const openRow = (table: Entry, attrs: Record<string, string>, st: St, bg = '', height = NaN) => {
    const row: Row = { cells: [] }
    if (bg) row.bg = bg
    if (height > 0) row.h = height
    ;(table.node as Table).rows.push(row)
    push({ tag: 'tr', el: { tag: 'tr', id: '', cls: [], link: false }, st, kind: 'row', node: row, vars: table.vars,
      ground: bg || table.ground })
  }
  const openCell = (row: Entry, tag: string, attrs: Record<string, string>, st: St, implicit = false,
    bg = '', width = NaN, height = NaN): Entry => {
    const cell: Box = { k: 'b', c: [] }
    const span = parseInt(attrs.colspan || '1', 10)
    if (span > 1) cell.span = Math.min(span, 50)
    if (bg) cell.bg = bg
    if (width > 0) cell.w = width
    else if (width < 0) cell.wpct = -width
    if (height > 0) cell.h = height
    ;(row.node as Row).cells.push(cell)
    const e: Entry = { tag, el: implicit ? { tag, id: '', cls: [], link: false } : row.el, st, kind: 'box', node: cell,
      flow: null, vars: row.vars, ground: bg || row.ground }
    if (!implicit) e.el = { tag, id: '', cls: [], link: false }
    push(e)
    return e
  }

  let skip = '' // the tag a skipped subtree started with
  let skipDepth = 0
  let skipNest = 0 // tables (lists) opened inside a skipped cell or row (item)

  const startTag = (tag: string, attrs: Record<string, string>, raw: string | null) => {
    if (skip) {
      // A hidden <li>, <p> or cell the page never closed ends at the next one,
      // but not at one of a table (list) inside it: Hacker News hides a
      // collapsed comment's row, which holds a table of its own.
      const scope = NEST[skip]
      if (scope && scope.includes(tag)) {
        skipNest++
        return
      }
      if (skipNest > 0 || !(OPTIONAL_END.has(skip) && (tag === skip || CLOSES[skip]?.includes(tag)))) {
        if (tag === skip && skipNest === 0) skipDepth++
        return
      }
      skip = ''
    }
    if (top().shut && tag !== 'summary') {
      // A closed <details>: what is not its summary is not shown.
      if (!VOID.has(tag) && raw === null) {
        skip = tag
        skipDepth = 1
        skipNest = 0
      }
      return
    }
    if (SKIP.has(tag) || (tag === 'input' && (attrs.type || '').toLowerCase() === 'hidden')) {
      if (tag === 'input') {
        const form = formOf()
        if (form !== undefined && form >= 0 && attrs.name) {
          page.forms[form].fields.push({ name: attrs.name, value: decode(attrs.value || ''), type: 'hidden' })
        }
        return
      }
      if (!VOID.has(tag) && raw === null) {
        skip = tag
        skipDepth = 1
        skipNest = 0
      }
      return
    }
    if (tag === 'html') {
      htmlAttrs = attrs
      styleRoot()
      return
    }
    if (tag === 'meta' && /^refresh$/i.test(attrs['http-equiv'] || '') && !page.refresh) {
      // <meta http-equiv="refresh" content="0; url=...">: soon, somewhere else.
      const m = /^\s*(\d+)(?:\.\d*)?\s*[;,]?\s*(?:url\s*=\s*)?['"]?([^'"]*)/i.exec(decode(attrs.content || ''))
      if (m && Number(m[1]) <= 10 && m[2].trim()) page.refresh = resolve(m[2].trim(), base)
      return
    }
    if (tag === 'head' || tag === 'tbody' || tag === 'thead' || tag === 'tfoot' || tag === 'colgroup' || tag === 'col'
      || tag === 'meta' || tag === 'link' || tag === 'base' || tag === 'wbr' || tag === 'source' || tag === 'track'
      || tag === 'param' || tag === 'area' || tag === 'picture') {
      return
    }

    // The HTML rules that close what a page left open.
    if (P_CLOSERS.has(tag)) {
      const p = find((e) => e.tag === 'p', tableScope)
      if (p > 0) popTo(p)
    }
    if (tag === 'li') {
      const li = find((e) => e.tag === 'li', (e) => tableScope(e) || e.tag === 'ul' || e.tag === 'ol')
      if (li > 0) popTo(li)
    } else if (tag === 'dt' || tag === 'dd') {
      const d = find((e) => e.tag === 'dt' || e.tag === 'dd', (e) => tableScope(e) || e.tag === 'dl')
      if (d > 0) popTo(d)
    } else if (tag === 'a') {
      const a = find((e) => e.tag === 'a', tableScope)
      if (a > 0) popTo(a)
    } else if (HEADING[tag] && HEADING[top().tag]) {
      popTo(stack.length - 1)
    } else if (tag === 'button') {
      const b = find((e) => e.tag === 'button', tableScope)
      if (b > 0) popTo(b)
    }

    // Table parts go where their table is, whatever was left open in it.
    if (tag === 'tr') {
      const t = find((e) => e.kind === 'table')
      if (t < 0) return
      popTo(t + 1)
    } else if (tag === 'td' || tag === 'th') {
      const r = find((e) => e.kind === 'row' || e.kind === 'table')
      if (r < 0) return
      popTo(r + 1)
      if (stack[r].kind === 'table') openRow(stack[r], {}, stack[r].st)
    } else if (tag === 'caption') {
      const t = find((e) => e.kind === 'table')
      if (t < 0) return
      popTo(t + 1)
    }

    const parent = top()
    const el: El = {
      tag,
      id: fold(attrs.id || ''),
      cls: classes(attrs.class),
      link: tag === 'a' && attrs.href !== undefined,
      attrs,
    }
    els.push(el)
    const look = styleFor(tag, attrs, parent)
    els.pop()
    if (look.display === 'none') {
      if (!VOID.has(tag) && raw === null) {
        skip = tag
        skipDepth = 1
        skipNest = 0
      }
      return
    }
    // The children of a flex box or a grid are blocks of their own, side by
    // side in a row (a row of links with no space between them in the page).
    if (parent.items && look.display !== 'block') look.display = 'block'
    // Those of an inline-flex (a button, a tab with its count) stay in its line.
    else if (parent.inl && look.display === 'block' && !BLOCK.has(tag)) look.display = ''
    const st = look.st
    // A form that posts (a login, a comment box) cannot be sent from here, and
    // a javascript: link does nothing without its script: both are dropped.
    if ((tag === 'form' && (attrs.method || '').toLowerCase() === 'post') ||
      (tag === 'a' && /^\s*javascript:/i.test(attrs.href || ''))) {
      skip = tag
      skipDepth = 1
      skipNest = 0
      return
    }

    switch (tag) {
      case 'body': {
