        // over it: what is set on <html> or :root (Tailwind's variables) and
        // on <body> reaches every element.
        if (stack.length > 1 && stack[1].tag === 'body') return
        styleRoot()
        els.push(el)
        const body = styleFor(tag, attrs, stack[0])
        els.pop()
        if (body.bg) page.bg = body.bg
        push({ tag, el, st: body.st, kind: 'box', node: root, flow: null, vars: body.vars, ground: body.ground })
        return
      }
      case 'br':
        addRun({ br: true, s: top().st })
        return
      case 'hr': {
        const e = sinkEntry()
        e.flow = null
        ;(e.node as Box).c.push({ k: 'hr' })
        return
      }
      case 'img': {
        if (st.hidden) return
        // What a page shows without its scripts (<noscript>): a counter's
        // pixel is no picture, nor a lazy picture's copy of the one before.
        if (find((x) => x.tag === 'noscript') > 0) {
          if (!attrs.width && !attrs.height && !(attrs.alt || '').trim()) return
          const flow = sinkEntry().flow
          const prev = flow && flow.runs.length ? (flow.runs[flow.runs.length - 1] as any) : null
          if (prev && prev.img && prev.img === resolve(decode(attrs.src || ''), base)) return
        }
        // A picture a script loads later keeps its address in a data-
        // attribute, a placeholder (an empty GIF, a blur) in its src.
        let src = attrs.src || ''
        const later = attrs['data-src'] || attrs['data-lazy-src'] || attrs['data-original'] || attrs['data-lazy'] || ''
        if (later && (!src || src.startsWith('data:') || /blank|placeholder|spacer|pixel|lazy|loading/i.test(src))) src = later
        const srcset = (!attrs.srcset || attrs.srcset.startsWith('data:') ? attrs['data-srcset'] || attrs['data-lazy-srcset'] : '') || attrs.srcset
        if (srcset) src = pickSrcset(decode(srcset), Math.min(viewport, 1024)) || src
        // A picture as wide as its box (w-full) keeps the shape its width and
        // height attributes give it.
        const pct = look.width < 0 ? -look.width : 0
        const aw = parseInt(attrs.width || '', 10)
        const ah = parseInt(attrs.height || '', 10)
        // A width of `auto` is the picture's own: its attributes say it (and
        // its shape), as wide as its box at most.
        const w = pct ? aw : look.width >= 0 ? look.width : aw > 0 ? aw : NaN
        const h = pct ? (aw > 0 ? ah : NaN) : look.height >= 0 ? look.height : aw > 0 && ah > 0 ? (w * ah) / aw : NaN
        const abs = src.startsWith('data:image/') ? src : resolve(decode(src), base)
        if ((w <= 2 && w >= 0) || (h <= 2 && h >= 0)) {
          // A spacer: Hacker News indents its comments with an empty picture.
          if (w > 2 || h > 2) addRun({ sp: true, w: w || 0, h: h || 0 })
          return
        }
        const alt = decode(attrs.alt || '').replace(/\s+/g, ' ').trim()
        const href = hrefOf()
        // An SVG is no picture a frame's <img> decodes (it sizes pictures as it
        // downloads them): its words instead.
        const svg = /\.svgz?(\?|#|$)/i.test(abs) || abs.startsWith('data:image/svg')
        if (svg && /^https?:/.test(abs) && (w > 0 || h > 0) && w <= 600 && h <= 600 && svgFile(abs)) {
          // Drawn as shapes, once it is downloaded (svg.ts).
          const run: any = { svg: abs, w: w > 0 ? w : 0, h: h > 0 ? h : 0 }
          if (href) run.a = href
          addRun(run)
          return
        }
        if (!abs || svg || !/^(https?:|data:image\/)/.test(abs) || page.stats.images >= maxImages) {
          if (alt) text(alt)
          return
        }
        if (look.abs) {
          // Pictures placed over each other (a crossfade, a carousel): the first.
          const sink = sinkEntry()
          const flow = sink.flow
          if (flow && flow.runs.length && (flow.runs[flow.runs.length - 1] as any).img) return
        }
        page.stats.images++
        const run: any = { img: abs, w: w || 0, h: h || 0, alt }
        if (pct) run.pct = pct
        if (look.cover) run.cover = true
        if (href) run.a = href
        addRun(run)
        return
      }
      case 'input': {
        const type = (attrs.type || 'text').toLowerCase()
        const form = formOf()
        if (form === undefined || form < 0) return
        const f = page.forms[form]
        if (type === 'submit' || type === 'button' || type === 'image') {
          if (type === 'submit' || type === 'image') {
            if (attrs.name) f.fields.push({ name: attrs.name, value: decode(attrs.value || ''), type: 'submit' })
            addRun({ btn: decode(attrs.value || attrs.alt || 'Submit'), form, s: st })
          }
          return
        }
        if (type === 'checkbox' || type === 'radio') {
          if (attrs.checked !== undefined && attrs.name) {
            f.fields.push({ name: attrs.name, value: decode(attrs.value || 'on'), type })
          }
          return
        }
        if (!/^(text|search|email|url|number|tel)$/.test(type) || !attrs.name) return
        f.fields.push({ name: attrs.name, value: decode(attrs.value || ''), type: 'text' })
        const size = parseInt(attrs.size || '20', 10)
        addRun({ field: f.fields.length - 1, form, size: size > 0 ? Math.min(size, 80) : 20, s: st,
          ph: decode(attrs.placeholder || '') })
        return
      }
      case 'svg': {
        // An SVG in the page: its shapes, at the size it is given.
        if (st.hidden || raw === null || svgBudget <= 0) return
        // The page's style sheets reach into it (a logo's paths colored by
        // the header they are in).
        const outer = (chain: El[]) => {
          if (!sheet.count) return null
          const at = els.length
          els.push(el, ...chain.slice(1))
          const found = matching(sheet, els)
          els.length = at
          if (!found.length) return null
          const out: Record<string, string> = {}
          for (const d of found) for (const k in d) out[k] = d[k].indexOf('var(') >= 0 ? resolveVars(d[k], look.vars).trim() : d[k]
          return out
        }
        const tree = parseSvg(raw, st.color, (v) => resolveVars(v, look.vars), outer)
        if (!tree) return
        let n = 0
        const count = (e: SvgEl) => {
          n++
          for (const c of e.c) count(c)
        }
        count(tree)
        if (n > svgBudget) return
        const aspect = svgAspect(tree)
        let w = look.width > 0 ? look.width : 0
        let h = look.height > 0 ? look.height : 0
        if (!w && h) w = h * aspect
        if (!h && w) h = w / aspect
        if (!(w > 0 && h > 0) || w > 1200 || h > 1200) return
        svgBudget -= n
        const run: any = { svg: '', tree, w, h }
        const href = hrefOf()
        if (href) run.a = href
        addRun(run)
        return
      }
      case 'textarea': {
        const form = formOf()
        if (form === undefined || form < 0 || !attrs.name) return
        const f = page.forms[form]
        f.fields.push({ name: attrs.name, value: decode(raw || ''), type: 'text' })
        addRun({ field: f.fields.length - 1, form, size: 40, s: st, ph: decode(attrs.placeholder || '') })
        return
      }
    }
    if (VOID.has(tag)) return

    const e: Entry = { tag, el, st, kind: 'inline', vars: look.vars, ground: look.ground, inl: look.inl || (parent.inl && look.display !== 'block') }
    if (look.display !== 'block' && look.apart & 1) text(' ')
    if (look.display !== 'block' && look.apart & 2) e.apart = true
    if (tag === 'a' && attrs.href !== undefined) {
      e.href = resolve(decode(attrs.href), base)
    }
    if (tag === 'form') {
      const method = (attrs.method || 'get').toLowerCase()
      const action = resolve(decode(attrs.action || ''), base) || base
      if (method === 'get' && /^https?:/.test(action)) {
        page.forms.push({ action: action.replace(/[?#].*$/, ''), fields: [] })
        e.form = page.forms.length - 1
      } else {
        e.form = -1 // a dialog's form, or one to another scheme: its fields go
      }
      e.kind = 'form'
      endFlow()
      push(e)
      return
    }
    if (tag === 'button') {
      const form = formOf()
      const type = (attrs.type || 'submit').toLowerCase()
      if (form !== undefined && form >= 0 && type === 'submit') {
        const run = { btn: '', form, s: st }
        addRun(run)
        e.btn = run
      } else {
        e.st = intern({ ...st, hidden: true })
        e.btn = { btn: '', form: -1, s: st } // its words are no button's: dropped
      }
      push(e)
      return
    }
    if (tag === 'table') {
      // A table starts its text at the left, as a browser in quirks mode does
      // (inside a <center>, Hacker News's cells are not centered).
      e.st = intern({ ...st, align: '' })
      const sink = sinkEntry()
      sink.flow = null
      const pad = parseInt(attrs.cellpadding ?? '1', 10)
      const sp = look.spacing >= 0 ? look.spacing : parseInt(attrs.cellspacing ?? '2', 10)
      const table: Table = { k: 'tab', pad: pad >= 0 ? Math.min(pad, 20) : 1, full: look.width === -100,
        border: parseInt(attrs.border || '0', 10) > 0, rows: [] }
      if (sp > 0) table.sp = Math.min(sp, 20)
      if (look.bg) table.bg = look.bg
      ;(sink.node as Box).c.push(table)
      e.kind = 'table'
      e.node = table
      push(e)
      return
    }
    if (tag === 'tr') {
      const t = stack[stack.length - 1]
      if (t.kind !== 'table') return
      openRow(t, attrs, st, look.bg, look.height)
      stack[stack.length - 1].el = el
      stack[stack.length - 1].vars = look.vars
      els[els.length - 1] = el
      return
    }
    if (tag === 'td' || tag === 'th') {
      const cell = openCell(top(), tag, attrs, st, false, look.bg, look.width, look.height)
      cell.el = el
      cell.vars = look.vars
      els[els.length - 1] = el
      if (st.align) (cell.node as Box).align = st.align
      return
    }
    if (tag === 'caption') {
      const t = top()
      openRow(t, {}, st)
      openCell(top(), 'td', { colspan: '50' }, intern({ ...st, align: 'center' }))
      top().el = el
      els[els.length - 1] = el
      return
    }
    if (look.display === 'block' && nest() >= maxNest) {
      // Past maxNest: its words on lines of their own in the box it is in.
      sinkEntry().flow = null
      e.flat = true
    } else if (look.display === 'block') {
      const sink = sinkEntry()
      sink.flow = null
      const box: Box = { k: 'b', c: [] }
      if (look.bg) box.bg = look.bg
      const m = MARGIN[tag]
      if (m) box.mt = box.mb = m * st.size
      if (look.mt >= 0) box.mt = Math.min(look.mt, 64)
      if (!isNaN(look.mb)) box.mb = Math.max(-32, Math.min(look.mb, 64))
      if (tag === 'ul' || tag === 'ol' || tag === 'menu' || tag === 'dir') {
        box.pl = 28
        e.list = { ordered: tag === 'ol', n: parseInt(attrs.start || '1', 10) || 1, none: look.listNone }
      }
      if (tag === 'dd') box.pl = 28
      if (tag === 'blockquote') {
        box.pl = 12
        box.bar = true
      }
      // The page's own padding (left, the list indent included, at most 200 px).
      const [pt, pr, pb, pl] = look.pad.map((n) => (n >= 0 ? Math.min(n, 200) : NaN))
      if (pl >= 0) box.pl = pl
      if (pt > 0 || pr > 0 || pb > 0) box.pad = [pt || 0, pr || 0, pb || 0]
      if (tag === 'li') {
        const list = find((x) => !!x.list, tableScope)
        const l = list > 0 ? (stack[list].list as { ordered: boolean; n: number; none: boolean }) : null
        if (!look.listNone && !(l && l.none)) box.mark = l && l.ordered ? `${l.n}.` : '•'
        if (l) l.n++
      }
      if (look.width > 0) box.w = look.width
      // A share of the box it is in (a grid's col-2 beside the rest).
      else if (look.width < 0 && look.width > -100) box.wpct = -look.width
      if (look.height > 0 && look.height < 2000) box.h = look.height
      if (look.bgsvg && box.w && box.h && box.w <= 200 && box.h <= 200 && svgFile(look.bgsvg)) {
        box.bgsvg = look.bgsvg
        if (look.ml > 0 || look.mr > 0) box.mx = [Math.min(look.ml || 0, 24), Math.min(look.mr || 0, 24)]
      }
      if (look.row) box.row = look.row
      if (look.items) e.items = true
      if (look.aspect) box.aspect = look.aspect
      if (tag === 'pre') box.bg = box.bg || '#f3f3f3'
      if (tag === 'details' && attrs.open === undefined) e.shut = true
      ;(sink.node as Box).c.push(box)
      e.kind = 'box'
      e.node = box
      e.flow = null
    }
    push(e)
  }

  const endTag = (tag: string) => {
    if (skip) {
      if (skipNest > 0) {
        if (NEST[skip]?.includes(tag)) skipNest--
        return
      }
      if (tag === skip) {
        if (--skipDepth === 0) skip = ''
        return
      }
      // A hidden <li> or <td> the page never closed ends with its list.
      if (!OPTIONAL_END.has(skip) || find((e) => e.tag === tag) <= 0) return
      skip = ''
    }
    if (tag === 'br') {
      addRun({ br: true, s: top().st })
      return
    }
    if (tag === 'body' || tag === 'html' || tag === 'head') return
    const tableTag = tag === 'table' || tag === 'tr' || tag === 'td' || tag === 'th' || tag === 'caption'
    const i = find(
      (e) => e.tag === tag,
      tableTag ? (e) => e.kind === 'table' && tag !== 'table' : tableScope
    )
    if (i <= 0) return
    const closing = stack[i]
    popTo(i)
    if (closing.kind === 'box' || closing.kind === 'table' || closing.kind === 'form' || closing.flat) endFlow()
    else if (closing.apart) text(' ')
  }

  // The tokenizer.
  const n = html.length
  let i = 0
  while (i < n) {
    const lt = html.indexOf('<', i)
    if (lt < 0) {
      if (!skip) text(html.slice(i))
      break
    }
    if (lt > i && !skip) text(html.slice(i, lt))
    i = lt
    const c = html.charCodeAt(i + 1)
    if (html.startsWith('<!--', i)) {
      const end = html.indexOf('-->', i + 4)
      i = end < 0 ? n : end + 3
      continue
    }
    if (c === 33 /* ! */ || c === 63 /* ? */) {
      const end = html.indexOf('>', i)
      i = end < 0 ? n : end + 1
      continue
    }
    const closing = c === 47 /* / */
    const nameStart = closing ? i + 2 : i + 1
    let j = nameStart
    while (j < n) {
      const ch = html.charCodeAt(j)
      if ((ch >= 97 && ch <= 122) || (ch >= 65 && ch <= 90) || (ch >= 48 && ch <= 57 && j > nameStart) || ch === 45 || ch === 58) j++
      else break
    }
    if (j === nameStart) {
      if (!skip) text('<')
      i++
      continue
    }
    const tag = html.slice(nameStart, j).toLowerCase()
    // The attributes, to the tag's ">" (one inside quotes does not end it).
    const attrs: Record<string, string> = {}
    let k = j
    while (k < n) {
      const ch = html[k]
      if (ch === '>') break
      if (ch === ' ' || ch === '\t' || ch === '\n' || ch === '\r' || ch === '\f' || ch === '/') {
        k++
        continue
      }
      let e = k
      while (e < n && !/[\s=>/]/.test(html[e])) e++
      const name = html.slice(k, e).toLowerCase()
      k = e
      while (k < n && /\s/.test(html[k])) k++
      let value = ''
      if (html[k] === '=') {
        k++
        while (k < n && /\s/.test(html[k])) k++
        const q = html[k]
        if (q === '"' || q === "'") {
          const end = html.indexOf(q, k + 1)
          value = html.slice(k + 1, end < 0 ? n : end)
          k = end < 0 ? n : end + 1
        } else {
          let e2 = k
          while (e2 < n && !/[\s>]/.test(html[e2])) e2++
          value = html.slice(k, e2)
          k = e2
        }
      }
      if (name && !(name in attrs)) attrs[name] = value
    }
    i = k + 1
    if (closing) {
      endTag(tag)
      continue
    }
    let raw: string | null = null
    if (RAW.has(tag) && !(tag === 'svg' && html[k - 1] === '/')) {
      const end = findClose(html, tag, i)
      // An <svg> is read whole, its own tag included.
      raw = html.slice(tag === 'svg' ? lt : i, end)
      const gt = html.indexOf('>', end)
      i = gt < 0 ? n : gt + 1
      if (tag === 'plaintext') i = n
      if (tag === 'svg') {
        if (!skip && raw.length <= MAX_SVG_TEXT) startTag(tag, attrs, raw + '</svg>')
        continue
      }
    }
    if (raw !== null && tag !== 'textarea') {
      // Raw text: a title or a style sheet is kept, the rest is junk.
      if (skip) continue
      if (tag === 'title' && !page.title) page.title = decode(raw).replace(/\s+/g, ' ').trim()
      else if (tag === 'style') addCss(sheet, raw, (ref) => resolve(decode(ref), base))
      continue
    }
    startTag(tag, attrs, raw)
    if (runs >= maxRuns) {
      page.truncated = true
      break
    }
  }

  page.stats.runs = runs
  cleanBox(root)
  return page
}

function findClose(html: string, tag: string, from: number): number {
  const re = new RegExp('</' + tag + '[\\s>/]', 'ig')
  re.lastIndex = from
  const m = re.exec(html)
  return m ? m.index : html.length
}

// Trims each flow and drops what shows nothing; a box around one box and
// nothing else of its own becomes that box; a table of one column becomes the
// boxes of its rows. Keeps the tree shallow for the layout's depth limit.
function hasText(flow: Flow): boolean {
  for (const r of flow.runs as any[]) {
    if (r.x !== undefined ? r.x.trim() !== '' && !r.s.hidden : !r.br) return true
  }
  return false
}

// Blank lines, where line breaks stand alone: a spacer as tall as their text.
const blank = (lines: number, s: St | undefined): Box => ({ k: 'b', c: [], h: Math.round(lines * (s ? s.size : 16) * 1.3) })

// A flow, trimmed, into `out`; the line breaks at its ends become blank lines
// as a browser draws them (one at its start is a line, the last at its end is
// none), and a flow of line breaks alone is that many.
function cleanFlow(flow: Flow, out: Node[]) {
  const runs = flow.runs as any[]
  let lead = 0
  while (lead < runs.length && runs[lead].br) lead++
  if (lead === runs.length) {
    if (lead && !flow.pre) out.push(blank(lead, runs[0].s))
    return
  }
  let tail = 0
  let last: any = null
  while (runs.length && runs[runs.length - 1].br) {
    last = runs.pop()
    tail++
  }
  const end = runs[runs.length - 1]
  if (end && end.x !== undefined && !flow.pre) end.x = end.x.replace(/ +$/, '')
  if (!hasText(flow)) return
  if (lead && !flow.pre) {
    out.push(blank(lead, runs[0].s))
    runs.splice(0, lead)
  }
  out.push(flow)
  if (tail > 1 && !flow.pre) out.push(blank(tail - 1, last.s))
}

function plain(box: Box): boolean {
  return !box.bg && !box.pl && !box.pad && !box.row && !box.aspect && !box.w && !box.h && !box.bar && !box.mark && !box.span && !box.wpct && !box.align &&
    !box.bgsvg
}

export function cleanBox(box: Box): Box | null {
  const out: Node[] = []
  const add = (c: Node) => {
    const prev = out[out.length - 1]
    if (c.k === 'b' && !c.c.length && c.h && !c.bg && prev && prev.k === 'b' && (prev.mb || 0) < 0) {
      // A negative bottom margin pulls up what follows: the blank line under
      // it shrinks (Hacker News's comment heads).
      c.h = Math.max(0, c.h + (prev.mb as number))
      prev.mb = undefined
      if (!c.h) return
    }
    out.push(c)
  }
  for (const child of box.c) {
    if (child.k === 't') {
      const parts: Node[] = []
      cleanFlow(child, parts)
      for (const c of parts) add(c)
      continue
    }
    let c: Node | null = child
    if (child.k === 'b') c = cleanBox(child)
    else if (child.k === 'tab') c = cleanTable(child)
    if (!c) continue
    if (c.k === 'b' && plain(c) && !c.mt && !c.mb && (!box.row || c.c.length <= 1)) {
      // A plain wrapper inside a box: its children are the box's (in a row,
      // only one alone: the row's items are what it holds).
      for (const g of c.c) add(g)
    } else add(c)
  }
  box.c = out
  if (!out.length && !box.h && !box.span && !box.w) return null
  if (out.length === 1 && out[0].k === 'b' && plain(box)) {
    const only = out[0] as Box
    only.mt = Math.max(only.mt || 0, box.mt || 0) || undefined
    only.mb = Math.max(only.mb || 0, box.mb || 0) || undefined
    return only
  }
  return box
}

function cleanTable(table: Table): Node | null {
  const rows: Row[] = []
  let cols = 0
  for (const row of table.rows) {
    const cells: Box[] = []
    let any = false
    for (const cell of row.cells) {
      // The cell stays (its width and span), with what it holds cleaned.
      cleanBox(cell)
      if (cell.c.length) any = true
      cells.push(cell)
    }
    if (!any) {
      // An empty row is room, or a line in the color of its cells (Hacker
      // News's orange rule over its footer).
      const bg = row.bg || (cells.find((c) => !!c.bg) || ({} as Box)).bg
      const h = row.h || (bg && cells.length ? Math.max(1, table.pad * 2) : 0)
      if (h) rows.push({ h, bg, cells: [] })
      continue
    }
    let width = 0
    for (const cell of cells) width += cell.span || 1
    cols = Math.max(cols, width)
    rows.push({ bg: row.bg, h: row.h, cells })
  }
  if (!rows.length) return null
  if (cols <= 1) {
    // One column: its rows, one under another.
    const box: Box = { k: 'b', c: [] }
    if (table.bg) box.bg = table.bg
    for (const row of rows) {
      if (!row.cells.length) {
        box.c.push(row.bg ? { k: 'b', c: [], h: row.h, bg: row.bg } : { k: 'b', c: [], h: row.h })
        continue
      }
      const cell = row.cells.find((c) => c.c.length) as Box
      if (!cell.bg && row.bg) cell.bg = row.bg
      if (!cell.h && row.h) cell.h = row.h
      cell.span = undefined
      cell.wpct = undefined
      if (!cell.bg && !cell.h && !cell.align && !cell.w) {
        for (const g of cell.c) box.c.push(g)
      } else box.c.push(cell)
    }
    return cleanBox(box)
  }
  table.rows = rows
  return table
}

sources.svg.ts:
// Small SVG pictures (a site's logo, its icons, Hacker News's Y and vote
// arrows): read into a tree of the shapes pixie draws, which view.tsx hands
// to the layout as an <svg> element. A frame's <img> does not decode SVG, so
// a page's SVG pictures, inline or linked, come this way, small ones only.

import { colorOf, parseColor } from './css'

export type SvgEl = { t: string; a: Record<string, string>; c: SvgEl[] }

export const MAX_SVG_TEXT = 16 * 1024
const MAX_ELEMENTS = 400
// What is drawn, as SVG spells it (the tokenizer reads names in lower case).
const TAGS: Record<string, string> = {
  svg: 'svg', g: 'g', path: 'path', rect: 'rect', circle: 'circle', ellipse: 'ellipse', line: 'line',
  polyline: 'polyline', polygon: 'polygon', defs: 'defs', lineargradient: 'linearGradient',
  radialgradient: 'radialGradient', stop: 'stop',
}
const SHAPES = new Set(['path', 'rect', 'circle', 'ellipse', 'line', 'polyline', 'polygon'])
const CAMEL: Record<string, string> = {
  viewbox: 'viewBox', gradientunits: 'gradientUnits', gradienttransform: 'gradientTransform',
  preserveaspectratio: 'preserveAspectRatio',
}
// Presentation properties a <style> or a style attribute may set.
const COLORS = new Set(['fill', 'stroke', 'stop-color', 'color'])
const PRESENT = new Set([
  'color', 'fill', 'fill-opacity', 'fill-rule', 'stroke', 'stroke-width', 'stroke-opacity', 'stroke-linecap',
  'stroke-linejoin', 'stroke-miterlimit', 'opacity', 'stop-color', 'stop-opacity', 'display', 'transform',
])

const unentity = (s: string) =>
  s.replace(/&(amp|lt|gt|quot|apos|#\d+|#x[0-9a-f]+);/gi, (all, e) => {
    const l = e.toLowerCase()
    if (l === 'amp') return '&'
    if (l === 'lt') return '<'
    if (l === 'gt') return '>'
    if (l === 'quot') return '"'
    if (l === 'apos') return "'"
    const code = l[1] === 'x' ? parseInt(l.slice(2), 16) : parseInt(l.slice(1), 10)
    return code > 0 && code < 0x110000 ? String.fromCodePoint(code) : ''
  })

function decls(text: string, into: Record<string, string>, over: boolean) {
  for (const item of text.split(';')) {
    const at = item.indexOf(':')
    if (at < 0) continue
    const name = item.slice(0, at).trim().toLowerCase()
    const value = item.slice(at + 1).replace(/!important/i, '').trim()
    if (PRESENT.has(name) && value && (over || !(name in into))) into[name] = value
  }
}

// An SVG document's markup as a tree, or null for one with nothing to draw
// (an empty one, a sprite of <use>s, one too big). Its colors are made ones
// pixie reads: `color` is what currentColor is, `vars` works out a var().
// `outer`: the page's style sheets for an element of it (an inline SVG is
// styled by the page: `.header .logo path { fill: ... }`), given the chain of
// its SVG elements from the root down.
export type SvgOuter = (chain: SvgTag[]) => Record<string, string> | null
export type SvgTag = { tag: string; id: string; cls: string[]; link: boolean; attrs?: Record<string, string> }

export function parseSvg(text: string, color = '#000000', vars?: (value: string) => string, outer?: SvgOuter): SvgEl | null {
  if (!text || text.length > MAX_SVG_TEXT) return null
  text = text.replace(/<!--[\s\S]*?-->/g, '')
  const rules: [string, string, string][] = [] // [tag, class, declarations] of its <style>
  const style = /<style[^>]*>([\s\S]*?)<\/style>/gi
  let m: RegExpExecArray | null
  while ((m = style.exec(text))) {
    const css = m[1].replace(/\/\*[\s\S]*?\*\//g, '')
    const rule = /([^{}]+)\{([^}]*)\}/g
    let r: RegExpExecArray | null
    while ((r = rule.exec(css))) {
      for (const sel of r[1].split(',')) {
        const s = /^\s*([a-z]*)(?:\.([\w-]+))?\s*$/i.exec(sel)
        if (s && (s[1] || s[2])) rules.push([s[1].toLowerCase(), s[2] || '', r[2]])
      }
    }
  }
  const tag = /<(\/?)([a-zA-Z][\w:-]*)((?:[^>"']|"[^"]*"|'[^']*')*?)(\/?)>/g
  const attr = /([\w:-]+)\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'>]+))/g
  let root: SvgEl | null = null
  const stack: SvgEl[] = []
  const chain: SvgTag[] = [] // the open elements, as the page's selectors see them
  const colors: string[] = [] // what currentColor is in each
  let skip = 0 // inside an element that is not drawn
  let count = 0
  let shapes = 0
  while ((m = tag.exec(text))) {
    const name = m[2].toLowerCase()
    if (m[1]) {
      if (skip) skip--
      else if (stack.length && stack[stack.length - 1].t === TAGS[name]) {
        stack.pop()
        chain.pop()
        colors.pop()
      }
      continue
    }
    const empty = m[4] === '/'
    const t = TAGS[name]
    if (skip || !t || (!root && t !== 'svg') || ++count > MAX_ELEMENTS) {
      if (!empty) skip++
      if (count > MAX_ELEMENTS) return null
      continue
    }
    const a: Record<string, string> = {}
    let css = ''
    let cls = ''
    attr.lastIndex = 0
    let p: RegExpExecArray | null
    while ((p = attr.exec(m[3]))) {
      const key = p[1].toLowerCase()
      const value = unentity(p[2] ?? p[3] ?? p[4] ?? '')
      if (key === 'style') css = value
      else if (key === 'class') cls = value
      else if (key === 'href' || key === 'xlink:href') {
        if (value[0] === '#') a.href = value
      } else if (!key.startsWith('on') && key.indexOf(':') < 0 && key !== 'xmlns') a[CAMEL[key] || key] = value
    }
    // Its <style>'s rules (by tag, by class), then its own style, over its attributes.
    for (const [rt, rc, d] of rules) {
      if ((!rt || rt === name) && (!rc || (' ' + cls + ' ').indexOf(' ' + rc + ' ') >= 0)) decls(d, a, true)
    }
    const me: SvgTag = { tag: name, id: a.id || '', cls: cls ? cls.trim().split(/\s+/) : [], link: false, attrs: a }
    if (outer) {
      chain.push(me)
      const d = outer(chain)
      chain.pop()
      if (d) for (const k in d) if (PRESENT.has(k) && d[k]) a[k] = d[k]
    }
    if (css) decls(css, a, true)
    const inherited = colors.length ? colors[colors.length - 1] : color
    let current = inherited
    if (a.color) {
      const c = a.color.indexOf('var(') >= 0 && vars ? vars(a.color).trim() : a.color
      current = /^(currentcolor|inherit)$/i.test(c) ? inherited : colorOf(c) || inherited
      delete a.color
    }
    for (const key in a) {
      if (!COLORS.has(key)) continue
      let v = a[key].trim()
      // A var() it cannot work out is most often the text's color.
      if (v.indexOf('var(') >= 0) v = (vars ? vars(v).trim() : '') || current
      if (/^currentcolor$/i.test(v)) v = current
      else if (v !== 'none' && !/^url\(/i.test(v)) v = colorOf(v) || (parseColor(v) ? 'none' : '')
      if (v) a[key] = v
      else delete a[key]
    }
    if (a.display === 'none') {
      if (!empty) skip++
      continue
    }
    const el: SvgEl = { t, a, c: [] }
    if (SHAPES.has(t)) shapes++
    if (!root) root = el
    else stack[stack.length - 1].c.push(el)
    if (!empty) {
      stack.push(el)
      chain.push(me)
      colors.push(current)
    }
  }
  if (!root || !shapes || !tidy(root)) return null
  const a = root.a
  if (!a.viewBox) {
    const w = parseFloat(a.width)
    const h = parseFloat(a.height)
    if (!(w > 0 && h > 0)) return null
    a.viewBox = `0 0 ${w} ${h}`
  }
  // The size is the page's to give.
  delete a.width
  delete a.height
  delete a.x
  delete a.y
  return root
}

// --- What the rasterizer reads. pixie's SVG reader takes plain numbers,
// user-space gradients and four transforms, and a page that hands it anything
// else fails as a whole: each attribute is made one it reads, or left out.

const NUM = /^[+-]?(\d+\.?\d*|\.\d+)(e[+-]?\d+)?$/i
// Numbers (a percentage only where marked 2: a gradient's coordinates, a stop).
const NUMERIC: Record<string, number> = {
  x: 1, y: 1, width: 1, height: 1, rx: 1, ry: 1, cx: 1, cy: 1, r: 1, x1: 1, y1: 1, x2: 1, y2: 1, fx: 1, fy: 1,
  'stroke-width': 1, 'stroke-miterlimit': 1, 'stroke-dashoffset': 1, offset: 2, opacity: 3, 'fill-opacity': 3,
  'stroke-opacity': 3, 'stop-opacity': 3,
}
const CHOICES: Record<string, Record<string, string>> = {
  'fill-rule': { nonzero: 'nonzero', evenodd: 'evenodd' },
  'stroke-linecap': { butt: 'butt', round: 'round', square: 'square' },
  'stroke-linejoin': { miter: 'miter', 'miter-clip': 'miter', arcs: 'miter', round: 'round', bevel: 'bevel' },
}

// A number pixie reads, or '' for none: `px` dropped, a percentage kept where
// it may be one, an opacity's made a fraction.
function plainNumber(value: string, kind: number, gradient: boolean): string {
  let v = value.trim().toLowerCase()
  if (v.endsWith('px')) v = v.slice(0, -2).trim()
  if (v.endsWith('%')) {
    const n = v.slice(0, -1).trim()
    if (!NUM.test(n)) return ''
    if (kind === 3) return String(parseFloat(n) / 100)
    return kind === 2 || gradient ? n + '%' : ''
  }
  return NUM.test(v) ? v : ''
}

function plainTransform(value: string): string {
  const parts = value.trim().replace(/\)\s*,\s*/g, ') ').match(/[a-z]+\s*\([^)]*\)/gi)
  if (!parts) return ''
  const out: string[] = []
  for (const part of parts) {
    const m = /^(matrix|translate|rotate|scale)\s*\(([^)]*)\)$/i.exec(part.trim())
    if (!m) return ''
    const args = m[2].trim().split(/[\s,]+/).filter((x) => x !== '')
    const want = m[1] === 'matrix' ? [6, 6] : m[1] === 'rotate' ? [1, 3] : [1, 2]
    if (args.length < want[0] || args.length > want[1] || args.some((x) => !NUM.test(x))) return ''
    out.push(`${m[1].toLowerCase()}(${args.join(' ')})`)
  }
  return out.join(' ')
}

const firstStop = (g: SvgEl | undefined) => (g && g.c.length ? g.c[0].a['stop-color'] || '' : '')
const urlId = (v: string) => {
  const m = /^url\(\s*["']?#([^"')]+)["']?\s*\)/i.exec(v.trim())
  return m ? m[1] : ''
}

// Makes the tree one pixie draws; false when it cannot be.
function tidy(root: SvgEl): boolean {
  const box = (root.a.viewBox || '').trim().split(/[\s,]+/)
  if (root.a.viewBox && (box.length !== 4 || box.some((x) => !NUM.test(x)))) delete root.a.viewBox
  // Gradients by id: one that takes another's (href) gets what it leaves out;
  // one pixie does not draw (its box's units) becomes its first color.
  const grads = new Map<string, SvgEl>()
  const each = (e: SvgEl, f: (e: SvgEl) => void) => {
    f(e)
    for (const c of e.c) each(c, f)
  }
  each(root, (e) => {
    if ((e.t === 'linearGradient' || e.t === 'radialGradient') && e.a.id) grads.set(e.a.id, e)
  })
  const solid = new Map<string, string>()
  for (const [id, g] of grads) {
    let from = g.a.href ? grads.get(g.a.href.slice(1)) : undefined
    for (let n = 0; from && n < 4; n++) {
      for (const k in from.a) if (!(k in g.a) && k !== 'id') g.a[k] = from.a[k]
      if (!g.c.length) g.c = from.c.map((c) => ({ t: c.t, a: { ...c.a }, c: [] }))
      from = from.a.href && from.a.href !== g.a.href ? grads.get(from.a.href.slice(1)) : undefined
    }
    delete g.a.href
    g.c = g.c.filter((c) => c.t === 'stop')
    for (const stop of g.c) {
      if (!stop.a['stop-color']) stop.a['stop-color'] = '#000000'
      if (!stop.a.offset) stop.a.offset = '0'
    }
    if (g.a.gradientUnits !== 'userSpaceOnUse' || g.c.length < 2) {
      solid.set(id, g.c.length ? g.c[0].a['stop-color'] : 'none')
      g.t = 'defs'
      g.c = []
      g.a = {}
    }
  }
  each(root, (e) => {
    for (const key in e.a) {
      const v = e.a[key]
      const kind = NUMERIC[key]
      let w: string | undefined = v
      if (kind) w = plainNumber(v, kind, e.t === 'linearGradient' || e.t === 'radialGradient')
      else if (CHOICES[key]) w = CHOICES[key][v.trim().toLowerCase()] || ''
      else if (key === 'transform' || key === 'gradientTransform') w = plainTransform(v)
      else if (key === 'stroke-dasharray') {
        // Zero-length dashes (a line drawn in by an animation, pathLength="1")
        // draw nothing; pixie draws no zero in a list at all.
        const list = v.trim().toLowerCase().replace(/px/g, '').split(/[\s,]+/)
        const n = list.map(parseFloat)
        if (list.some((x) => !NUM.test(x)) || n.some((x) => x < 0)) w = ''
        else if (n.length % 2 === 0 && n.every((x, i) => i % 2 || x === 0) && n.some((x) => x > 0)) {
          w = ''
          e.a.stroke = 'none'
        } else w = n.some((x) => x === 0) ? '' : list.join(' ')
      } else if (key === 'fill' || key === 'stroke') {
        const id = urlId(v)
        // pixie fills with a gradient, and strokes with a color alone.
        if (id) w = key === 'fill' && grads.has(id) && !solid.has(id) ? `url(#${id})` : solid.get(id) || firstStop(grads.get(id)) || 'none'
        else if (/^url\(/i.test(v.trim())) w = 'none'
      }
      if (w) e.a[key] = w
      else delete e.a[key]
    }
  })
  return true
}

// The width over the height of a tree's viewBox, or 1.
export function svgAspect(el: SvgEl): number {
  const v = (el.a.viewBox || '').trim().split(/[\s,]+/).map(parseFloat)
  return v.length === 4 && v[2] > 0 && v[3] > 0 ? v[2] / v[3] : 1
}

sources.css.ts:
// A small cascade: the rules of a page's stylesheets and <style> blocks, read
// for the few properties this browser draws (colors, sizes, weight, slant,
// decoration, case, alignment, what is hidden, white space, margins and
// padding, a cell's width and a row's height). Selectors are tags, classes
// (escapes included: Tailwind's `.md\:hidden`), ids, `*`, `:root` and
// `:link`, attributes (`[width='40']`, `[href^=http]`), joined by descendant
// (`a b`) or child (`a > b`, read as descendant) combinators; anything else
// (`:hover`, `:where()`, siblings) is a rule that never applies. @layer and @supports are read
// through, @media by the width the page is laid out at, the rest skipped.
// Custom properties cascade and inherit, and var() and calc() are worked out
// where a value is read. Colors become #rrggbb, whatever they were written as
// (oklch, lab, hsl, color-mix: Tailwind 4's palette), over white.

export type Decl = Record<string, string>
// One compound selector: a tag, an id, classes, :link, and attributes
// ([name, operator, value]: '' for one that is only there).
// not: compounds none of which may match (:not()).
// parent: the next part's element is this one's child (`>`), not any descendant.
// all: lists of compounds one of each of which must match (:is(), :where(), each of them).
type Part = { tag: string; id: string; cls: string[]; link: boolean; at?: [string, string, string][]; not?: Part[];
  all?: Part[][]; parent?: boolean }
// need: what its ancestors must hold (needs()); seen: the last matching() that looked at it.
export type Rule = { parts: Part[]; spec: number; order: number; decl: Decl; need?: string[]; seen?: number }
// What a selector is matched against: an element on the open stack.
export type El = { tag: string; id: string; cls: string[]; link: boolean; attrs?: Record<string, string> }
// `width`: the page's width in CSS pixels, for @media.
// `url`: a sheet's url()s against its own address. `fold`: a page without a
// doctype (quirks mode, Hacker News) matches classes and ids in any case.
export type Sheet = { byKey: Map<string, Rule[]>; count: number; width: number; url?: (ref: string) => string; fold?: boolean;
  max: number }
export type Vars = Record<string, string>

const MAX_RULES = 8000
const MAX_TEXT = 512 * 1024
// The properties anything here reads (and every custom property); the rest
// are not kept.
const KEPT = new Set([
  'color', 'background', 'background-color', 'background-image', 'font-size', 'font-weight', 'font-style', 'font-family', 'font',
  'text-decoration', 'text-decoration-line', 'text-align', 'text-transform', 'display', 'visibility',
  'white-space', 'width', 'height', 'position', 'clip', 'clip-path', 'list-style', 'list-style-type',
  'padding', 'padding-top', 'padding-right', 'padding-bottom', 'padding-left', 'padding-inline',
  'padding-inline-start', 'padding-inline-end', 'padding-block', 'margin', 'margin-top', 'margin-block',
  'margin-block-start', 'margin-block-end', 'margin-bottom', 'margin-left', 'margin-right', 'margin-inline-start',
  'margin-inline-end', 'top', 'left', 'bottom', 'inset', 'opacity', 'transform', 'translate', 'border-collapse', 'border-spacing',
  'fill', 'stroke', 'stroke-width', 'fill-opacity', 'stroke-opacity',
  'flex-direction', 'flex-flow', 'flex-wrap', 'gap', 'column-gap', 'row-gap', 'justify-content', 'aspect-ratio', 'object-fit',
])

export function newSheet(width = 640, fold = false, max = MAX_RULES): Sheet {
  return { byKey: new Map(), count: 0, width, fold, max }
}

// --- Selectors.

const isIdent = (c: string | undefined) => !!c && (/[\w-]/.test(c) || c.charCodeAt(0) > 127)

// An identifier at `i`, its escapes read (`\:`, `\/`, and `\32 ` for "2").
const IDENT = /(?:[\w-]|[^\x00-\x7f]|\\[0-9a-fA-F]{1,6} ?|\\[\s\S])+/y
function ident(s: string, i: number): [string, number] {
  IDENT.lastIndex = i
  const m = IDENT.exec(s)
  if (!m) return ['', i]
  const raw = m[0]
  const name = raw.indexOf('\\') < 0 ? raw : raw.replace(/\\([0-9a-fA-F]{1,6} ?|[\s\S])/g, (all, e) =>
    /^[0-9a-fA-F]/.test(e) ? String.fromCodePoint(parseInt(e, 16)) : e)
  return [name, i + raw.length]
}

// States a page drawn on a frame is never in.
const NEVER = /^:(hover|focus|focus-within|focus-visible|active|visited|checked|disabled|target|placeholder-shown|open|popover-open|modal|fullscreen|autofill|invalid|user-invalid)$/i

function parseSelector(text: string, fold = false): { parts: Part[]; spec: number } | null {
  const s = text.trim()
  const parts: Part[] = []
  let spec = 0
  let cur: Part | null = null
  let i = 0
  while (i < s.length) {
    const c = s[i]
    if (c === ' ' || c === '\n' || c === '\t' || c === '>') {
      if (cur) parts.push(cur)
      cur = null
      // `a > b`: b's parent is a (the part before it is marked).
      if (c === '>') {
        if (!parts.length) return null
        parts[parts.length - 1].parent = true
      }
      i++
      continue
    }
    if (!cur) cur = { tag: '', id: '', cls: [], link: false }
    if (c === '.' || c === '#') {
      const [raw, next] = ident(s, i + 1)
      if (!raw) return null
      const name = fold ? raw.toLowerCase() : raw
      if (c === '.') cur.cls.push(name)
      else cur.id = name
      spec += c === '#' ? 10000 : 100
      i = next
    } else if (c === ':') {
      const [raw, next] = ident(s, i + 1)
      const name = raw.toLowerCase()
      i = next
      if (name === 'link' || name === 'any-link') cur.link = true
      else if (name === 'root') cur.tag = 'html'
      else if ((name === 'not' || name === 'is' || name === 'where' || name === 'matches') && s[i] === '(') {
        // A list of compound selectors (no combinators): a state this page
        // never is in (:hover) is one that does not match.
        let depth = 0
        let end = i
        for (; end < s.length; end++) {
          if (s[end] === '(') depth++
          else if (s[end] === ')' && --depth === 0) break
        }
        const alts: Part[] = []
        let most = 0
        for (const inner of split(s.slice(i + 1, end), ',')) {
          if (NEVER.test(inner.trim())) continue
          // One this cascade does not read (`.prose *`, a sibling) is taken
          // as one that does not match: an opt-out, most often.
          const sel = parseSelector(inner, fold)
          if (!sel || sel.parts.length !== 1) continue
          alts.push(sel.parts[0])
          most = Math.max(most, sel.spec)
        }
        i = end + 1
        if (name === 'not') {
          if (alts.length) (cur.not || (cur.not = [])).push(...alts)
        } else if (!alts.length) return null
        else if (alts.length === 1) {
          // One compound: its tests are this one's (`.a:where(.b):where([x])`
          // is all three).
          const one = alts[0]
          if (one.tag) cur.tag = one.tag
          if (one.id) cur.id = one.id
          if (one.link) cur.link = true
          cur.cls.push(...one.cls)
          if (one.at) (cur.at || (cur.at = [])).push(...one.at)
          if (one.not) (cur.not || (cur.not = [])).push(...one.not)
          if (one.all) (cur.all || (cur.all = [])).push(...one.all)
        } else (cur.all || (cur.all = [])).push(alts)
        spec += name === 'where' ? 0 : most
        continue
      } else return null
      spec += 100
    } else if (c === '[') {
      const end = s.indexOf(']', i)
      if (end < 0) return null
      const m = /^\s*([\w-]+)\s*(?:([~^$*|]?=)\s*(?:"([^"]*)"|'([^']*)'|([^\s"']+))\s*(i)?)?\s*$/i.exec(s.slice(i + 1, end))
      if (!m) return null
      const ci = !!m[6]
      const value = m[3] ?? m[4] ?? m[5] ?? ''
      ;(cur.at || (cur.at = [])).push([m[1].toLowerCase(), m[2] ? (ci ? 'i' : '') + m[2] : '', ci ? value.toLowerCase() : value])
      spec += 100
      i = end + 1
    } else if (c === '*') {
      i++
    } else if (isIdent(c)) {
      const [name, next] = ident(s, i)
      cur.tag = name.toLowerCase()
      spec += 1
      i = next
    } else return null // [attr], +, ~, and the like
  }
  if (cur) parts.push(cur)
  return parts.length ? { parts, spec } : null
}

// The parts of a list split at its top-level commas (or spaces).
function split(text: string, by: string): string[] {
  if (text.indexOf('(') < 0) {
    const parts = by === ' ' ? text.split(/\s+/) : text.split(by)
    const out: string[] = []
    for (const p of parts) {
      const t = p.trim()
      if (t) out.push(t)
    }
    return out
  }
  const out: string[] = []
  let depth = 0
  let start = 0
  for (let i = 0; i < text.length; i++) {
    const c = text[i]
    if (c === '(') depth++
    else if (c === ')') depth--
    else if (depth === 0 && (by === ' ' ? /\s/.test(c) : c === by)) {
      if (i > start) out.push(text.slice(start, i))
      start = i + 1
    }
  }
  if (start < text.length) out.push(text.slice(start))
  return out.map((p) => p.trim()).filter((p) => p !== '')
}

export function parseDecls(text: string): Decl {
  const decl: Decl = {}
  for (const item of split(text, ';')) {
    const at = item.indexOf(':')
    if (at < 0) continue
    const name = item.slice(0, at).trim()
    const custom = name.startsWith('--')
    const key = custom ? name : name.toLowerCase()
    if (!custom && !KEPT.has(key)) continue
    const value = item
      .slice(at + 1)
      .replace(/!\s*important\s*$/i, '')
      .trim()
    // `initial` is what an unset custom property is: left out, it is inherited
    // instead, which is close enough for Tailwind's `--tw-*: initial` resets.
    if (value && !(custom && value === 'initial')) decl[key] = value
  }
  return decl
}

// --- Media queries: the width the page is laid out at, a light screen.

function mediaMatches(query: string, width: number): boolean {
  for (const each of split(query, ',')) {
    let q = each.toLowerCase().trim()
    let negate = false
    if (q.startsWith('not ')) {
      negate = true
      q = q.slice(4)
    }
    q = q.replace(/^only\s+/, '')
    let ok = true
    for (const raw of q.split(/\s+and\s+/)) {
      const c = raw.trim()
      if (c === 'all' || c === 'screen' || !c) continue
      const m = /^\(\s*([a-z-]+)\s*(?::\s*([^)]*))?\)$/.exec(c)
      const range = /^\(\s*width\s*(>=|<=|>|<)\s*([^)]+)\)$/.exec(c)
      if (m) {
        const value = (m[2] || '').trim()
        if (m[1] === 'min-width') ok = width >= lengthOf(value, 16)
        else if (m[1] === 'max-width') ok = width <= lengthOf(value, 16)
        else if (m[1] === 'prefers-color-scheme') ok = value === 'light'
        else ok = /^(hover|any-hover|pointer|any-pointer|prefers-reduced-motion|orientation|color)$/.test(m[1])
      } else if (range) {
        const n = lengthOf(range[2], 16)
        const op = range[1]
        ok = op === '>=' ? width >= n : op === '<=' ? width <= n : op === '>' ? width > n : width < n
      } else ok = false
      if (!ok) break
    }
    if (negate ? !ok : ok) return true
  }
  return false
}

// Where a block that starts at `at` (just past its "{") ends.
const BRACE = /[{}]/g
function blockEnd(text: string, at: number): number {
  let depth = 1
  BRACE.lastIndex = at
  let m: RegExpExecArray | null
  while ((m = BRACE.exec(text))) {
    if (m[0] === '{') depth++
    else if (--depth === 0) return m.index
  }
  return text.length
}

function addRules(sheet: Sheet, text: string, from: number, to: number) {
  let at = from
  while (at < to && sheet.count < sheet.max) {
    const open = text.indexOf('{', at)
    if (open < 0 || open >= to) break
    const semi = text.indexOf(';', at)
    let head = text.slice(at, open).trim()
    if (semi >= 0 && semi < open && head[0] === '@') {
      // A statement (@import, @charset, `@layer a, b;`).
      at = semi + 1
      continue
    }
    const close = blockEnd(text, open + 1)
    if (head[0] === '@') {
      const name = (/^@([a-z-]+)/i.exec(head) || ['', ''])[1].toLowerCase()
      if (name === 'layer' || name === 'supports' || (name === 'media' && mediaMatches(head.slice(6), sheet.width))) {
        addRules(sheet, text, open + 1, close)
      }
    } else {
      const decl = parseDecls(text.slice(open + 1, close))
      const bg = decl['background-image'] || decl.background
      if (bg && sheet.url && bg.indexOf('url(') >= 0) {
        const abs = bg.replace(/url\(\s*(["']?)([^"')]*)\1\s*\)/g, (all, q, ref) => `url("${(sheet.url as any)(ref)}")`)
        if (decl['background-image']) decl['background-image'] = abs
        else decl.background = abs
      }
      if (Object.keys(decl).length) {
        for (const selText of split(head, ',')) {
          const sel = parseSelector(selText, sheet.fold)
          if (!sel) continue
          const last = sel.parts[sel.parts.length - 1]
          const key = last.id ? '#' + last.id : last.cls.length ? '.' + last.cls[0] : last.tag || '*'
          const list = sheet.byKey.get(key)
          const rule: Rule = { parts: sel.parts, spec: sel.spec, order: sheet.count++, decl, need: needs(sel.parts) }
          if (list) list.push(rule)
          else sheet.byKey.set(key, [rule])
        }
      }
    }
    at = close + 1
  }
}

// A style sheet cut down to what addCss would keep of it at `width`: the
// rules whose selectors it reads, with the properties it reads, @media
// worked out, @layer and @supports opened, the rest (@font-face, @keyframes,
// :hover rules, transitions, grid templates) gone. A news site's 2.7 MB of
// component styles is a few hundred kilobytes of it; the order is kept, so the
// cascade is the same.
const UNREAD = /::|[+~](?![^[]*\])|:(hover|active|visited|checked|first|last|nth|only|empty|has|before|after|placeholder|target|focus-within|focus-visible|indeterminate|autofill|popover-open|fullscreen)(?![\w-])/i
// `classes`: the classes a page's elements have (pageClasses). A selector that
// names one no element has can match nothing on it and goes too (a :not(),
// :is() or :where() asks nothing of the page): a design system's 400 KB of
// utilities is the few dozen KB this page uses, so all of a site's sheets fit
// where only a few did.
export function slimCss(text: string, width: number, classes?: Set<string>): string {
  const src = text.replace(/\/\*[\s\S]*?(\*\/|$)/g, '')
  const out: string[] = []
  slimRules(src, 0, src.length, width, classes, out)
  return out.join('\n')
}

// slimCss's walk, a function of its own: a closure that calls itself is a
// cycle QuickJS frees only at its next collection, and it held the sheet's
// text (on an ESP32, a few sheets of it were the JS heap's 4 MB).
function slimRules(src: string, from: number, to: number, width: number, classes: Set<string> | undefined, out: string[]) {
  let at = from
  while (at < to) {
    const open = src.indexOf('{', at)
    if (open < 0 || open >= to) break
    const semi = src.indexOf(';', at)
    const head = src.slice(at, open).trim()
    if (semi >= 0 && semi < open && head[0] === '@') {
      at = semi + 1
      continue
    }
    const close = Math.min(blockEnd(src, open + 1), to)
    if (head[0] === '@') {
      const name = (/^@([a-z-]+)/i.exec(head) || ['', ''])[1].toLowerCase()
      if (name === 'layer' || name === 'supports' || (name === 'media' && mediaMatches(head.slice(6), width))) {
        slimRules(src, open + 1, close, width, classes, out)
      }
    } else {
      // Selectors this cascade never matches (states, siblings, what is
      // before or after an element) go; the rest are read by addCss.
      const sels = split(head, ',').filter((sel) => !UNREAD.test(sel.replace(/:not\([^()]*\)/g, '')) &&
        (!classes || canMatch(sel, classes)))
      if (sels.length) {
        const decl = parseDecls(src.slice(open + 1, close))
        const body: string[] = []
        for (const k in decl) body.push(k + ':' + decl[k])
        if (body.length) out.push(sels.join(',') + '{' + body.join(';') + '}')
      }
    }
    at = close + 1
  }
}

// The classes of a page's elements, in any case as well (a quirks-mode page
// matches them so).
export function pageClasses(html: string): Set<string> {
  const out = new Set<string>()
  const re = /\sclass\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>"']+))/gi
  let m: RegExpExecArray | null
  while ((m = re.exec(html))) {
    for (const c of (m[1] ?? m[2] ?? m[3] ?? '').split(/\s+/)) {
      if (!c) continue
      out.add(c)
      out.add(c.toLowerCase())
    }
  }
  return out
}

// Whether every class a selector names (outside :not(), :is() and :where())
// is one the page has.
function canMatch(sel: string, classes: Set<string>): boolean {
  let text = sel
  for (let i = 0; i < 3 && /:(not|is|where|matches)\(/i.test(text); i++) text = text.replace(/:(not|is|where|matches)\([^()]*\)/gi, '')
  for (let i = text.indexOf('.'); i >= 0; i = text.indexOf('.', i + 1)) {
    if (i > 0 && text[i - 1] === '\\') continue
    // Inside [attr="a.b"] a dot is no class.
    const open = text.lastIndexOf('[', i)
    if (open >= 0 && text.indexOf(']', open) > i) continue
    const [name] = ident(text, i + 1)
    if (name && !/^\d/.test(name) && !classes.has(name) && !classes.has(name.toLowerCase())) return false
  }
  return true
}

// `url`: what the sheet's relative url()s are against.
export function addCss(sheet: Sheet, source: string, url?: (ref: string) => string) {
  const text = source.slice(0, MAX_TEXT).replace(/\/\*[\s\S]*?(\*\/|$)/g, '')
  sheet.url = url
  addRules(sheet, text, 0, text.length)
  sheet.url = undefined
}

function partMatches(part: Part, el: El): boolean {
  if (part.tag && part.tag !== el.tag) return false
  if (part.id && part.id !== el.id) return false
  if (part.link && !el.link) return false
  for (const c of part.cls) if (el.cls.indexOf(c) < 0) return false
  if (part.not) for (const alt of part.not) if (partMatches(alt, el)) return false
  if (part.all) for (const alts of part.all) if (!alts.some((alt) => partMatches(alt, el))) return false
  if (part.at) {
    for (const [name, op, want] of part.at) {
      let v = el.attrs ? el.attrs[name] : undefined
      if (v === undefined) return false
      if (op[0] === 'i') v = v.toLowerCase()
      switch (op.replace('i', '')) {
        case '=':
          if (v !== want) return false
          break
        case '~=':
          if (v.split(/\s+/).indexOf(want) < 0) return false
          break
        case '^=':
          if (!want || !v.startsWith(want)) return false
          break
        case '$=':
          if (!want || !v.endsWith(want)) return false
          break
        case '*=':
          if (!want || v.indexOf(want) < 0) return false
          break
        case '|=':
          if (v !== want && !v.startsWith(want + '-')) return false
          break
      }
    }
  }
  return true
}

// Whether a rule's selector matches the element on top of `stack`.
function matches(rule: Rule, stack: El[]): boolean {
  const parts = rule.parts
  let p = parts.length - 1
  if (!partMatches(parts[p], stack[stack.length - 1])) return false
  p--
  if (p < 0) return true
  // What its ancestors must be (a class, an id, a tag of each), looked up in
  // the set of what the open elements are before walking them.
  if (rule.need) {
    const anc = ancestry(stack, stack.length - 2)
    for (const k of rule.need) if (!anc.has(k)) return false
  }
  return above(parts, p, stack, stack.length - 2)
}

// Whether parts[0..p] match the elements from stack[i] up: parts[p] the
// element at i if it is a parent (`>`), else at i or any above it.
function above(parts: Part[], p: number, stack: El[], i: number): boolean {
  if (p < 0) return true
  if (parts[p].parent) return i >= 0 && partMatches(parts[p], stack[i]) && above(parts, p - 1, stack, i - 1)
  for (; i >= 0; i--) {
    if (partMatches(parts[p], stack[i]) && above(parts, p - 1, stack, i - 1)) return true
  }
  return false
}

// The keys (#id, .class, tag) of stack[0..i], kept on stack[i] (an element's
// ancestors do not change while it is open).
type Keyed = El & { anc?: Set<string>; ancOf?: El }
function ancestry(stack: El[], i: number): Set<string> {
  const el = stack[i] as Keyed
  if (i < 0) return new Set()
  if (el.anc && el.ancOf === (i > 0 ? stack[i - 1] : undefined)) return el.anc
  const anc = new Set(i > 0 ? ancestry(stack, i - 1) : undefined)
  anc.add(el.tag)
  if (el.id) anc.add('#' + el.id)
  for (const c of el.cls) anc.add('.' + c)
  el.anc = anc
  el.ancOf = i > 0 ? stack[i - 1] : undefined
  return anc
}

// The keys a selector's ancestor parts need, or undefined for none.
function needs(parts: Part[]): string[] | undefined {
  const need: string[] = []
  for (let i = 0; i < parts.length - 1; i++) {
    const p = parts[i]
    if (p.id) need.push('#' + p.id)
    for (const c of p.cls) need.push('.' + c)
    if (p.tag) need.push(p.tag)
  }
  return need.length ? need : undefined
}

// The declarations that apply to the element on top of `stack`, the more
// specific (then the later) last, so a plain loop over them cascades.
let stamp = 0
export function matching(sheet: Sheet, stack: El[]): Decl[] {
  if (!sheet.count) return []
  const el = stack[stack.length - 1]
  const found: Rule[] = []
  const now = ++stamp
  const take = (key: string) => {
    const list = sheet.byKey.get(key)
    if (list) {
      for (const rule of list) {
        if (rule.seen === now) continue
        rule.seen = now
        if (matches(rule, stack)) found.push(rule)
      }
    }
  }
  if (el.id) take('#' + el.id)
  for (const c of el.cls) take('.' + c)
  take(el.tag)
  take('*')
  if (found.length > 1) found.sort((a, b) => a.spec - b.spec || a.order - b.order)
  return found.map((r) => r.decl)
}

// --- Values.

// `value` with its var()s replaced: the custom property, else the fallback.
export function resolveVars(value: string, vars: Vars, depth = 0): string {
  if (value.indexOf('var(') < 0 || depth > 8) return value
  let out = ''
  let i = 0
  for (;;) {
    const j = value.indexOf('var(', i)
    if (j < 0) {
      out += value.slice(i)
      break
    }
    out += value.slice(i, j)
    let k = j + 4
    let level = 1
    let comma = -1
    for (; k < value.length; k++) {
      const c = value[k]
      if (c === '(') level++
      else if (c === ')' && --level === 0) break
      else if (c === ',' && level === 1 && comma < 0) comma = k
    }
    const name = value.slice(j + 4, comma < 0 ? k : comma).trim()
    let v = vars[name]
    if (v === undefined || v === '') v = comma < 0 ? '' : value.slice(comma + 1, k)
    out += resolveVars(v, vars, depth + 1)
    i = k + 1
  }
  return out
}

const KEYWORD_SIZES: Record<string, number> = {
  'xx-small': 9, 'x-small': 10, small: 13, medium: 16, large: 18, 'x-large': 24, 'xx-large': 32,
}

// A number with its unit in CSS pixels (`len`), or a plain number.
type Num = { n: number; len: boolean }

function unit(n: number, u: string, of: number): Num | null {
  switch (u) {
    case '':
      return { n, len: false }
    case 'px':
      return { n, len: true }
    case 'pt':
      return { n: (n * 4) / 3, len: true }
    case 'em':
      return { n: n * of, len: true }
    case 'rem':
      return { n: n * 16, len: true }
    case 'ex':
    case 'ch':
      return { n: n * of * 0.5, len: true }
    case '%':
      return { n: (n * of) / 100, len: true }
  }
  return null
}

// calc(): + - * / and parentheses over lengths and numbers.
function calc(expr: string, of: number): number {
  const s = expr.replace(/calc\(/g, '(')
  let i = 0
  const space = () => {
    while (s[i] === ' ') i++
  }
  const factor = (): Num | null => {
    space()
    if (s[i] === '(') {
      i++
      const v = sum()
      space()
      if (s[i] !== ')') return null
      i++
      return v
    }
    const m = /^-?(\d+\.?\d*|\.\d+)(e-?\d+)?([a-z%]*)/i.exec(s.slice(i))
    if (!m) return null
    i += m[0].length
    return unit(parseFloat(m[0]), m[3].toLowerCase(), of)
  }
  const product = (): Num | null => {
    let a = factor()
    for (;;) {
      space()
      const op = s[i]
      if (!a || (op !== '*' && op !== '/')) return a
      i++
      const b = factor()
      if (!b) return null
      a = op === '*' ? { n: a.n * b.n, len: a.len || b.len } : { n: a.n / b.n, len: a.len }
    }
  }
  const sum = (): Num | null => {
    let a = product()
    for (;;) {
      space()
      const op = s[i]
      if (!a || (op !== '+' && op !== '-')) return a
      i++
      const b = product()
      if (!b) return null
      a = { n: op === '+' ? a.n + b.n : a.n - b.n, len: a.len || b.len }
    }
  }
  const v = sum()
  return v && i >= s.length ? v.n : NaN
}

// A length in CSS pixels; `of` is what % and em are of. NaN for what is not one.
export function lengthOf(value: string | undefined, of: number): number {
  if (!value) return NaN
  const v = value.trim().toLowerCase()
  if (v in KEYWORD_SIZES) return KEYWORD_SIZES[v]
  if (v === 'smaller') return of / 1.2
  if (v === 'larger') return of * 1.2
  if (v.startsWith('calc(')) return calc(v, of)
  const m = /^(-?[\d.]+)([a-z%]*)$/.exec(v)
  if (!m) return NaN
  const n = unit(parseFloat(m[1]), m[2], of)
  return n ? n.n : NaN
}

// The four sides of a margin or padding shorthand: top, right, bottom, left.
export function sides(value: string, of: number): number[] {
  const p = split(value, ' ').map((x) => lengthOf(x, of))
  if (p.length === 1) return [p[0], p[0], p[0], p[0]]
  if (p.length === 2) return [p[0], p[1], p[0], p[1]]
  if (p.length === 3) return [p[0], p[1], p[2], p[1]]
  return [p[0], p[1], p[2], p[3]]
}

// --- Colors.

const NAMED: Record<string, string> = {
  black: '000000', white: 'ffffff', red: 'ff0000', green: '008000', blue: '0000ff', gray: '808080', grey: '808080',
  silver: 'c0c0c0', maroon: '800000', navy: '000080', purple: '800080', teal: '008080', olive: '808000',
  orange: 'ffa500', yellow: 'ffff00', lime: '00ff00', aqua: '00ffff', cyan: '00ffff', fuchsia: 'ff00ff',
  magenta: 'ff00ff', brown: 'a52a2a', pink: 'ffc0cb', gold: 'ffd700', darkgray: 'a9a9a9', darkgrey: 'a9a9a9',
  lightgray: 'd3d3d3', lightgrey: 'd3d3d3', dimgray: '696969', dimgrey: '696969', darkblue: '00008b',
  darkred: '8b0000', darkgreen: '006400', whitesmoke: 'f5f5f5', gainsboro: 'dcdcdc', beige: 'f5f5dc',
  ivory: 'fffff0', tomato: 'ff6347', crimson: 'dc143c', indigo: '4b0082', violet: 'ee82ee', coral: 'ff7f50',
  salmon: 'fa8072', khaki: 'f0e68c', tan: 'd2b48c', steelblue: '4682b4', royalblue: '4169e1', slategray: '708090',
  darkorange: 'ff8c00', firebrick: 'b22222', seagreen: '2e8b57', skyblue: '87ceeb', lightblue: 'add8e6',
  lavender: 'e6e6fa', linen: 'faf0e6', snow: 'fffafa', honeydew: 'f0fff0', aliceblue: 'f0f8ff',
}

type Rgba = [number, number, number, number] // 0-255, alpha 0-1

const gamma = (x: number) => 255 * (x <= 0.0031308 ? 12.92 * x : 1.055 * Math.pow(x, 1 / 2.4) - 0.055)
const num = (s: string, scale = 1) => (s.endsWith('%') ? (parseFloat(s) / 100) * scale : parseFloat(s))

function oklab(l: number, a: number, b: number): [number, number, number] {
  const l_ = Math.pow(l + 0.3963377774 * a + 0.2158037573 * b, 3)
  const m_ = Math.pow(l - 0.1055613458 * a - 0.0638541728 * b, 3)
  const s_ = Math.pow(l - 0.0894841775 * a - 1.291485548 * b, 3)
  return [
    gamma(4.0767416621 * l_ - 3.3077115913 * m_ + 0.2309699292 * s_),
    gamma(-1.2684380046 * l_ + 2.6097574011 * m_ - 0.3413193965 * s_),
    gamma(-0.0041960863 * l_ - 0.7034186147 * m_ + 1.707614701 * s_),
  ]
}

function cielab(l: number, a: number, b: number): [number, number, number] {
  const fy = (l + 16) / 116
  const fx = fy + a / 500
  const fz = fy - b / 200
  const f = (t: number) => (t > 6 / 29 ? t * t * t : 3 * (6 / 29) * (6 / 29) * (t - 4 / 29))
  const x = 0.96422 * f(fx)
  const y = f(fy)
  const z = 0.82521 * f(fz)
  // XYZ (D50) to linear sRGB, the Bradford adaptation folded in.
  return [
    gamma(3.1338561 * x - 1.6168667 * y - 0.4906146 * z),
    gamma(-0.9787684 * x + 1.9161415 * y + 0.033454 * z),
    gamma(0.0719453 * x - 0.2289914 * y + 1.4052427 * z),
  ]
}

function hsl(h: number, s: number, l: number): [number, number, number] {
  const k = (n: number) => (n + h / 30) % 12
  const a = s * Math.min(l, 1 - l)
  const f = (n: number) => 255 * (l - a * Math.max(-1, Math.min(k(n) - 3, 9 - k(n), 1)))
  return [f(0), f(8), f(4)]
}

export function parseColor(value: string): Rgba | null {
  const v = value.trim().toLowerCase()
  if (v === 'transparent') return [0, 0, 0, 0]
  let hex = v[0] === '#' ? v.slice(1) : NAMED[v] || (/^[0-9a-f]{6}$/.test(v) ? v : '') // <font color="ff6600">
  if (hex && /^[0-9a-f]+$/.test(hex)) {
    if (hex.length === 3 || hex.length === 4) hex = hex.split('').map((c) => c + c).join('')
    if (hex.length !== 6 && hex.length !== 8) return null
    const n = (i: number) => parseInt(hex.slice(i, i + 2), 16)
    return [n(0), n(2), n(4), hex.length === 8 ? n(6) / 255 : 1]
  }
  const m = /^([a-z-]+)\((.*)\)$/.exec(v)
  if (!m) return null
  const fn = m[1]
  if (fn === 'color-mix') {
    // color-mix(in <space>, A [p%], B [q%]): Tailwind's opacity (B transparent).
    const args = split(m[2], ',').slice(1)
    if (args.length !== 2) return null
    const take = (s: string): [Rgba | null, number] => {
      const pm = /\s(\d+\.?\d*)%$/.exec(s) || /^(\d+\.?\d*)%\s/.exec(s)
      return [parseColor(pm ? s.replace(pm[0], '').trim() : s), pm ? parseFloat(pm[1]) / 100 : NaN]
    }
    const [a, pa] = take(args[0])
    const [b, pb] = take(args[1])
    if (!a || !b) return null
    const wa = !isNaN(pa) ? pa : !isNaN(pb) ? 1 - pb : 0.5
    const wb = 1 - wa
    const alpha = a[3] * wa + b[3] * wb
    if (alpha <= 0) return [0, 0, 0, 0]
    const mix = (i: number) => (a[i] * a[3] * wa + b[i] * b[3] * wb) / alpha
    return [mix(0), mix(1), mix(2), alpha]
  }
  const parts = m[2].replace(/,/g, ' ').replace(/\//g, ' / ').trim().split(/\s+/)
  const slash = parts.indexOf('/')
  const alpha = slash >= 0 ? num(parts[slash + 1] || '1') : parts.length === 4 ? num(parts[3]) : 1
  const p = slash >= 0 ? parts.slice(0, slash) : parts.slice(0, 3)
  if (p.length < 3 || p.some((x) => x === 'none' ? false : isNaN(parseFloat(x)))) return null
  const x = p.map((s) => (s === 'none' ? '0' : s))
  let rgb: [number, number, number]
  switch (fn) {
    case 'rgb':
    case 'rgba':
      rgb = [num(x[0], 255), num(x[1], 255), num(x[2], 255)]
      break
    case 'hsl':
    case 'hsla':
      rgb = hsl(parseFloat(x[0]), num(x[1]) > 1 ? num(x[1]) / 100 : num(x[1]), num(x[2]) > 1 ? num(x[2]) / 100 : num(x[2]))
      break
    case 'oklab':
      rgb = oklab(num(x[0]), num(x[1], 0.4), num(x[2], 0.4))
      break
    case 'oklch': {
      const h = (parseFloat(x[2]) * Math.PI) / 180
      const c = num(x[1], 0.4)
      rgb = oklab(num(x[0]), c * Math.cos(h), c * Math.sin(h))
      break
    }
    case 'lab':
      rgb = cielab(num(x[0], 100), num(x[1], 125), num(x[2], 125))
      break
    case 'lch': {
      const h = (parseFloat(x[2]) * Math.PI) / 180
      const c = num(x[1], 150)
      rgb = cielab(num(x[0], 100), c * Math.cos(h), c * Math.sin(h))
      break
    }
    default:
      return null
  }
  return [rgb[0], rgb[1], rgb[2], isNaN(alpha) ? 1 : Math.max(0, Math.min(1, alpha))]
}

const hex2 = (n: number) => Math.max(0, Math.min(255, Math.round(n))).toString(16).padStart(2, '0')

// A color the UI can draw, as #rrggbb (a see-through one over white), or ''
// for none.
export function colorOf(value: string | undefined): string {
  if (!value) return ''
  const c = parseColor(value)
  if (!c || c[3] <= 0.05) return ''
  const over = (n: number) => n * c[3] + 255 * (1 - c[3])
  return '#' + hex2(over(c[0])) + hex2(over(c[1])) + hex2(over(c[2]))
}

// The color in a `background` shorthand: 'transparent' for none, '' when it
// says none we can read.
export function backgroundOf(value: string | undefined): string {
  if (!value) return ''
  const v = value.trim()
  if (/^(none|transparent|initial|unset)$/i.test(v)) return 'transparent'
  const whole = colorOf(v)
  if (whole) return whole
  if (/gradient\(|url\(/i.test(v)) return ''
  for (const word of split(v, ' ')) {
    const c = parseColor(word)
    if (c) return c[3] <= 0.05 ? 'transparent' : colorOf(word)
  }
  return ''
}

