import { get, onEvent, normalize } from './app'
import { convert, resolve, scanHead, slimmer, slimPush, slimText } from './html'
import { pageClasses, slimCss } from './css'
import { partsOf } from './view'
import { parseSvg } from './svg'

// Hacker News's front page as it is built: a table of tables, the story rows
// in threes, a style sheet for the colors, and a GET form for the search.
const HN = `<html lang="en" op="news"><head><link rel="stylesheet" type="text/css" href="news.css?x1">
<title>Hacker News</title><script>var junk = "<b>not text</b>"</script><style>.gone { display: none }</style></head>
