const ITEM = `<html><body><table><tr><td><span class="commtext">A comment with <a href="https://example.org/x">a link</a> and <i>words</i>.<p>Second paragraph<pre><code>  indented code</code></pre></span></td></tr></table></body></html>`

// Every string in the tree, in order.
function texts(node: any, into: string[] = []): string[] {
  if (node === null || node === undefined || node === false || node === true) return into
  if (typeof node === 'string' || typeof node === 'number') into.push(String(node))
  else if (Array.isArray(node)) node.forEach((child) => texts(child, into))
  else if (node.props) texts(node.props.children, into)
  return into
}

function find(node: any, test: (n: any) => boolean): any {
  if (!node || typeof node !== 'object') return null
  if (Array.isArray(node)) {
    for (const child of node) {
      const hit = find(child, test)
      if (hit) return hit
    }
    return null
  }
  if (test(node)) return node
  return node.props ? find(node.props.children, test) : null
}

// What the tree says, its spaces (a link's no-break ones too) as one.
const said = (tree: any) => texts(tree).join(' ').replace(/\s+/g, ' ')

// The element that says `text` and takes a tap.
const tappable = (tree: any, text: string) =>
  find(tree, (n) => !!n.props && typeof n.props.onClick === 'function' && texts(n).join('') === text)

let fetched: string[] = []
// Pages by address; a key ending in * answers every address it starts.
function serve(pages: Record<string, string>) {
  fetched = []
  return mock.frameos('useFetch' as any, (url: string) => {
    fetched.push(url)
    let body = pages[url]
    if (body === undefined) {
      for (const key in pages) if (key.endsWith('*') && url.startsWith(key.slice(0, -1))) body = pages[key]
    }
    if (body === undefined) return { data: undefined, error: 'getaddrinfo ENOTFOUND', loading: false, ok: false, status: 0 }
    return { data: body, loading: false, ok: true, status: 200 }
  })
}

