// Every run of a page, in order.
function runsOf(page: any): any[] {
  const runs: any[] = []
  const walk = (n: any) => {
    if (n.k === 't') runs.push(...n.runs)
    else if (n.k === 'b') n.c.forEach(walk)
    else if (n.k === 'tab') n.rows.forEach((r: any) => r.cells.forEach(walk))
  }
  walk(page.root)
  return runs
}
const wordsOf = (page: any) => runsOf(page).filter((r) => r.x !== undefined).map((r) => r.x).join(' ')

