// The page a server answers in byte ranges (206), as big sites' caches do.
function serveRanged(pages: Record<string, string>) {
  fetched = []
  return mock.frameos('useFetch' as any, (url: string, init: any) => {
    const range = init && init.headers && init.headers.Range
    fetched.push(url + (range ? ' ' + range : ''))
    const body = pages[url]
    if (body === undefined) return { data: undefined, error: 'getaddrinfo ENOTFOUND', loading: false, ok: false, status: 0 }
    const m = /^bytes=(\d+)-(\d+)$/.exec(range || '')
    if (!m) return { data: body, loading: false, ok: true, status: 200 }
    const from = Number(m[1])
    if (from >= body.length) return { data: '', loading: false, ok: false, status: 416 }
    return { data: body.slice(from, Number(m[2]) + 1), loading: false, ok: true, status: 206 }
  })
}

const slim = (pieces: string[], css = 512 * 1024) => {
  const s = slimmer(css, 600)
  pieces.forEach((p, i) => slimPush(s, p, i === pieces.length - 1))
  return slimText(s)
}

describe('the common web', () => {
  it('reads a page megabytes long in pieces, keeping its words and not its scripts', () => {
    const junk = '<script>' + 'var x = "<p>not words</p>";'.repeat(120000) + '</script>'
    const page = '<!doctype html><html><head><title>News</title>' + junk + '<style>.a{color:red} .a:hover{color:blue} @keyframes k{0%{opacity:0}}</style></head>' +
      '<body><svg width="10" viewBox="0 0 10 10"><path d="M0 0h10v10z"/></svg><p class="a">The words</p></body></html>'
    serveRanged({ 'https://big.example/': page })
    const app = browser()
    app.state.homepage = 'https://big.example/'
    const tree = show(app)
    expect(page.length).toBeGreaterThan(3 * 1024 * 1024)
    expect(fetched[0]).toBe('https://big.example/ bytes=0-2097151')
    expect(fetched[1]).toBe('https://big.example/ bytes=2097152-4194303')
    expect(said(tree)).toContain('The words')
    expect(said(tree)).not.toContain('not words')
  })

  it('slims the same, whole or cut anywhere', () => {
    const page = '<html><head><style>p{color:red;transition:all 1s}@media (min-width:900px){p{color:blue}}</style>' +
      '<script>if (a < b) document.write("<b>")</script></head><body><!-- a comment --><p title="a > b">one</p>' +
      '<div data-props="' + 'x'.repeat(100) + '" class="c">two</div></body></html>'
    const whole = slim([page])
    expect(whole).not.toContain('script')
    expect(whole).not.toContain('comment')
    expect(whole).not.toContain('transition')
    expect(whole).not.toContain('blue')
    expect(whole).toContain('p{color:red}')
    expect(whole).toContain('<p title="a > b">one</p>')
    expect(whole).not.toContain('xxxx')
    for (const at of [10, 30, 50, 75, 100, 140, 160, 200]) {
      expect(slim([page.slice(0, at), page.slice(at)]).replace(/\n/g, '')).toBe(whole.replace(/\n/g, ''))
    }
  })

  it('keeps of a style sheet what this browser reads at the page width', () => {
    const css = `@font-face{font-family:x;src:url(x.woff)} a:hover{color:red} .x::before{content:"x"} .n{color:#123456;animation:spin 1s}
@media (max-width:700px){.m{display:none}} @media (min-width:1200px){.w{display:none}} @supports (display:grid){.g{gap:4px}}`
    expect(slimCss(css, 600)).toBe('.n{color:#123456}\n.m{display:none}\n.g{gap:4px}')
  })

  it('matches :not(), :is() and :where(), and a state this frame is never in as not being in it', () => {
    const css = `.nav:not(.open) .menu{display:none} :where(ul) li{color:#111111} .t:is(.a, .b){color:#222222} .s:not(:focus){position:absolute;width:1px;height:1px}`
    const html = '<div class="nav"><div class="menu">menu words</div></div><ul><li>item</li></ul><span class="t b">is</span><span class="s">screen reader</span><p>after</p>'
    const page = convert('<!doctype html>' + html, 'https://x.org/', { sheets: [css] })
    const runs = runsOf(page)
    expect(wordsOf(page)).not.toContain('menu words')
    expect(wordsOf(page)).not.toContain('screen reader')
    expect(runs.find((r) => r.x === 'item').s.color).toBe('#111111')
    expect(runs.find((r) => r.x === 'is').s.color).toBe('#222222')
