// An ESP32: robots.txt answers a range (the host sends pages in pieces), unless `whole`.
function board(frame: Record<string, any> = {}, whole: Record<string, number> = {}) {
  const asked: string[] = []
  mock.frameos('httpRequest' as any, (url: string, init: any) => {
    asked.push((init && init.method) || 'GET')
    if (url.endsWith('/robots.txt')) return { status: Object.keys(whole).some((u) => url.startsWith(u.replace(/\/[^/]*$/, ''))) ? 200 : 206, body: 'User-agent' }
    return { status: 200, headers: whole[url] ? { 'content-length': String(whole[url]) } : {} }
  })
  const app = makeApp({ frame: { embedded: true, fast: true, ...frame } })
  return { app, asked }
}

const LONG = '<html><body>' + Array.from({ length: 300 }, (_, i) => `<p>Paragraph ${i} has <a href="/p${i}">a link</a> in its words, as text with links does.</p>`).join('') + '</body></html>'

describe('a board short of memory', () => {
  it('draws a long page in parts, and the next part when asked', () => {
    serve({ 'https://long.example/': LONG })
    const { app } = board()
    app.state.homepage = 'https://long.example/'
    let tree = show(app)
    const next = find(tree, (n) => n.props && typeof n.props.onClick === 'function' && /^Part 2 of \d+ ›$/.test(texts(n).join('')))
    expect(next).toBeTruthy()
    expect(said(tree)).toContain('Paragraph 0 has')
    expect(said(tree)).not.toContain('Paragraph 299 has')
    next.props.onClick({})
    tree = show(app)
    expect(said(tree)).toContain('‹ Part 1 of')
    expect(said(tree)).not.toContain('Paragraph 0 has')
    expect(frameos.recall('nav').list[0].p).toBe(1)
  })

  it('draws a page whole where there is room for it', () => {
    serve({ 'https://long.example/': LONG })
    const app = browser()
    app.state.homepage = 'https://long.example/'
    const words = said(show(app))
    expect(words).toContain('Paragraph 299 has')
    expect(words).not.toContain('Part 2 of')
  })

  it('keeps its own pictures, no bigger than it needs, and lets them go with the page', () => {
    serve({ 'https://pics.example/': '<p>Photo</p><img src="/a.jpg" width="800" height="600"><a href="/b">Next</a>', 'https://pics.example/b': '<p>Another page</p>' })
    const { app } = board({ paper: true, fast: false })
    const fetches: any[] = []
    mock.frameos('fetchImage' as any, (url: string, options: any) => {
      fetches.push({ url, ...options })
      return { image: { __frameosType: 'imageRef', id: 7 }, width: options.width, height: options.height }
    })
    const released = mock.frameos('releaseImage' as any, () => true)
    app.state.homepage = 'https://pics.example/'
    const tree = show(app)
    expect(fetches.length).toBe(1)
    expect(fetches[0].url).toBe('https://pics.example/a.jpg')
    expect(fetches[0].keep).toBe(true)
    expect(fetches[0].width * fetches[0].height).toBeLessThanOrEqual(120000)
    expect(find(tree, (n) => n.type === 'img' && n.props.src && n.props.src.id === 7)).toBeTruthy()
    tappable(tree, 'Next').props.onClick({})
    expect(said(show(app))).toContain('Another page')
    expect(released.calls.length).toBe(1)
  })

  it('underlines a link with a border under its words, not text drawn as outlines', () => {
    serve({ 'https://u.example/': '<p>Read <a href="/x">story</a> now</p>' })
    const { app } = board()
    app.state.homepage = 'https://u.example/'
    const link = tappable(show(app), 'story')
    expect(link.props.className).toContain('border-b')
    expect(link.props.className).not.toContain('underline')
  })

  it('lets a page go before it downloads the next, where downloads come in the render', () => {
    serve(PAGES)
    const { app } = board()
    const sleep = mock.frameos('setNextSleep' as any, () => {})
    tappable(show(app), 'frames').props.onClick({})
    const count = fetched.length
    const between = said(show(app))
    expect(between).toContain('Loading example.com')
    expect(fetched.length).toBe(count)
    expect(sleep.calls[sleep.calls.length - 1][0]).toBe(1)
    expect(said(show(app))).toContain('Second paragraph')
  })

  it('does not download a page too big for it from a server that sends pages only whole', () => {
    serve({ 'https://whole.example/big': '<p>Big</p>' })
    const { app } = board({}, { 'https://whole.example/big': 5 * 1024 * 1024 })
    app.state.homepage = 'https://whole.example/big'
    const words = said(show(app))
    expect(words).toContain('This page did not load')
    expect(words).toContain('only whole')
    expect(fetched.length).toBe(0)
  })
})

// The words of each text flow of a page, in order.
function flowsOf(node: any, into: string[] = []): string[] {
  if (node.k === 't') into.push(node.runs.map((r: any) => r.x || '').join(''))
  for (const c of node.c || []) flowsOf(c, into)
  for (const r of node.rows || []) for (const c of r.cells) flowsOf(c, into)
  return into
}

// The boxes of a page, depth first.
function boxes(node: any, into: any[] = []): any[] {
  if (node.k === 'b') into.push(node)
  for (const c of node.c || []) boxes(c, into)
  for (const r of node.rows || []) for (const c of r.cells) boxes(c, into)
  return into
}

describe('a design system’s pages (GitHub as the test case)', () => {
  it('keeps of a big sheet the rules the page’s classes can match', () => {
    const classes = pageClasses('<div class="sr-only Box"><a class="d-flex">x</a></div>')
    const css = '.sr-only{position:absolute;width:1px}.btn-danger{color:#ff0000}.Box .d-flex{display:flex}' +
      '.Box:not(.open){color:#111111}:where(.nope) .Box{color:#222222}.x .Box{color:#333333}:root{--fg:#444444}'
    const slim = slimCss(css, 600, classes)
    expect(slim).toContain('.sr-only{')
    expect(slim).toContain('.Box .d-flex{')
    expect(slim).toContain('.Box:not(.open){')
    expect(slim).toContain(':where(.nope) .Box{')
    expect(slim).toContain(':root{')
    expect(slim).not.toContain('btn-danger')
    expect(slim).not.toContain('.x .Box')
  })

  it('takes two :where()s on one element as both, not the last alone', () => {
    const page = convert('<a class="b" data-size="small" href="/c">2,380 Commits</a>', 'https://x.org/',
      { sheets: ['.b:where(.icon):where([data-size=small]){display:none}'] })
    expect(flowsOf(page.root).join(' ')).toContain('Commits')
  })

  it('keeps what an inline-flex holds in its line: a tab, its icon and its count', () => {
    const page = convert('<p><a class="tab" href="/i">Issues<span class="count">5</span></a> then more</p>', 'https://x.org/',
      { sheets: ['.tab{display:inline-flex}.count{display:flex;margin-left:8px}'] })
    const line = flowsOf(page.root).find((f) => f.indexOf('Issues') >= 0) || ''
    expect(line).toContain('5')
    expect(line).toContain('then more')
  })

  it('keeps a wrapper in a flex row an item of its own, and gives a box its share of the width', () => {
    const lines = (n: number, w: string) => Array.from({ length: n }, (_, i) => `<div>${w}${i}</div>`).join('')
    const page = convert(`<div style="display:flex"><div style="width:72px">${lines(20, '')}</div><div>${lines(20, 'code ')}</div></div>` +
      '<div style="display:flex"><div style="width:25%">avatar</div><div>name</div></div>', 'https://x.org/')
    const rows = boxes(page.root).filter((b) => b.row)
    expect(rows[0].c.length).toBe(2)
    expect(rows[1].c[0].wpct).toBe(25)
  })

  it('cuts columns side by side into parts line by line, the same lines of each', () => {
    const lines = (n: number, w: string) => Array.from({ length: n }, (_, i) => `<div>${w} ${i} ${'x'.repeat(60)}</div>`).join('')
    const page = convert(`<div style="display:flex"><div style="width:40px">${lines(200, 'n')}</div><div>${lines(200, 'code')}</div></div>`, 'https://x.org/')
    const parts = partsOf(page, 600)
    expect(parts.starts.length).toBeGreaterThan(2)
    const row = boxes(page.root).find((b) => b.row)
    const [numbers, code] = row.c.map((c: any) => { while (c.c.length === 1 && c.c[0].k === 'b') c = c.c[0]; return c.c })
    // The second part starts at the same line of both columns.
    const at = parts.starts[1]
    const firstIn = (list: any[]) => list.findIndex((n: any) => n.$a >= at)
    expect(firstIn(numbers)).toBe(firstIn(code))
  })

  it('links a site’s own sheets and its fonts and code, not its other themes', () => {
    const head = '<link rel="stylesheet" href="/light.css"><link rel="stylesheet" href="/dark.css"><link rel="stylesheet" href="/high_contrast.css">' +
      '<link rel="stylesheet" href="/primer.css"><link rel="stylesheet" href="/code-view.css">'
    const sheets = scanHead(head, 'https://x.org/', 24).sheets
    expect(sheets).toEqual(['https://x.org/light.css', 'https://x.org/primer.css', 'https://x.org/code-view.css'])
  })

  it('opens @media, @layer and @supports inside each other in a sheet it slims', () => {
    const css = '@layer base{@media (min-width:1px){@supports (display:grid){.Box{color:#123456}}}}' +
      '@media (min-width:9000px){.Box{color:#654321}}'
    const slim = slimCss(css, 600, pageClasses('<div class="Box">x</div>'))
    expect(slim).toContain('.Box{color:#123456}')
    expect(slim).not.toContain('#654321')
  })

  it('draws boxes nested past maxNest as lines of the box they are in, every word kept', () => {
    // GitHub's front page is 26 boxes deep: a walk of it a call a level ran
    // past an ESP32's 20 KB of JS stack.
    const html = '<p>top</p>' + '<div class="w"><p>wrapped</p>'.repeat(30) + '<p>deep</p>' + '</div>'.repeat(30) + '<p>after</p>'
    const depth = (n: any): number => (n.k === 'b' ? 1 + Math.max(0, ...n.c.map(depth)) : 0)
    const sheets = ['.w{padding:4px}']
    const deep = convert(html, 'https://x.org/', { sheets })
    const flat = convert(html, 'https://x.org/', { sheets, maxNest: 8 })
    expect(depth(deep.root)).toBeGreaterThan(20)
    expect(depth(flat.root)).toBeLessThanOrEqual(8)
    const words = flowsOf(flat.root)
    expect(words.filter((w) => w.indexOf('wrapped') >= 0).length).toBe(30)
    expect(words.join(' ')).toContain('deep')
    expect(words[words.length - 1]).toContain('after')
  })
})
